「막따 · 맑다 · 짤따 · 짧다」',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":9,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"낱말대로 바르게 쓴 것은 모두 몇 개인가요?\n「막따 · 맑다 · 짤따 · 짧다」","options":[{"t":"2개 (맑다·짧다)","correct":true},{"t":"4개","mis":"K1-2-u2-X04"},{"t":"1개 (맑다)","mis":"K1-2-u2-X04"}],"explanation":["「맑다」와 「짧다」가 낱말대로 쓴 것이에요.","「막따」·「짤따」는 소리대로 쓴 것이에요.","하나씩 뜻과 받침을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;

