INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C1','kor',1,2,'u2',3,'글자의 짜임과 받침 — 첫소리·가운뎃소리·끝소리 세 자리, 쌍받침(같은 자음자 둘)과 겹받침(다른 자음자 둘) 구별·찾기',ARRAY['2국04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C2','kor',1,2,'u2',5,'받침에 주의하며 낱말 쓰기 — 소리와 글자가 다를 때 소리대로가 아니라 낱말대로 쓰기(값·없다·맑다)',ARRAY['2국03-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C3','kor',1,2,'u2',7,'받침이 있는 낱말 바르게 읽기 — 겹받침 뒤에 모음이 오면 둘 다, 자음이 오거나 끝이면 하나만 소리 남, ㅟ 바르게 읽기',ARRAY['2국02-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C4','kor',1,2,'u2',9,'글쓴이가 하고 싶은 말 찾기 — 글쓴이 알기, 제목과 쓴 까닭을 이어서 하고 싶은 말 찾기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C5','kor',1,2,'u2',11,'인물의 생각 알기 — 인물이 한 말과 행동에서 생각을 짐작하기, 같은 물음에 답이 다를 수 있음',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u2-C6','kor',1,2,'u2',13,'둘레의 글에서 받침 낱말 찾아 쓰기 — 알림판·책·초대장에서 겹받침 낱말 찾기, 낱말 카드에 바르게 쓰기',ARRAY['2국04-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X01','kor',1,'u2',ARRAY['K1-2-u2-C1']::text[],'쌍받침과 겹받침 이름을 뒤바꾼다 (ㄲ을 겹받침으로, ㄺ을 쌍받침으로)','「같은 자음자가 겹쳤나, 다른 자음자 둘인가」 받침만 따로 써 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X02','kor',1,'u2',ARRAY['K1-2-u2-C1','K1-2-u2-C6']::text[],'받침이 하나인 글자나 받침이 없는 글자를 겹받침 글자로 고른다 (강·우산·손잡이)','글자를 첫소리·가운뎃소리·끝소리 세 칸으로 나눠 쓰고 끝소리 칸에 자음자가 몇 개인지 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X03','kor',1,'u2',ARRAY['K1-2-u2-C1']::text[],'글자의 세 자리를 모른다 — 첫소리 자리 자음자 두 개(ㄸ·ㅃ)를 받침으로 보거나 끝소리 자리에 모음을 둔다','「맑」을 ㅁ·ㅏ·ㄺ 세 조각으로 떼어 자리 이름을 붙여 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X04','kor',1,'u2',ARRAY['K1-2-u2-C2']::text[],'소리 나는 대로 쓴다 (값→갑, 없다→업다, 맑다→막다, 얇다→얄다)','「소리는 하나만 나도 쓸 때는 낱말대로」 — 뜻을 먼저 떠올리고 받침을 정하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X05','kor',1,'u2',ARRAY['K1-2-u2-C2']::text[],'겹받침의 짝을 틀리거나 자리를 바꿔 쓴다 (값→갌, 읽다→릭다, 넓다→넒다)','그 낱말이 들어간 문장을 뜻으로 읽고 바른 받침 짝을 눈으로 확인하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X06','kor',1,'u2',ARRAY['K1-2-u2-C2']::text[],'소리가 같은 다른 낱말과 헷갈린다 (없다/업다, 값/갑, 앉다/안다)','두 낱말을 나란히 놓고 「뜻이 무엇인지」 그림이나 몸으로 견주게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X07','kor',1,'u2',ARRAY['K1-2-u2-C3']::text[],'뒤에 자음이 오거나 낱말이 끝나도 겹받침 두 소리를 다 낸다 (넓고→[넓고], 값→[갑스])','「뒤에 무엇이 오나요?」 자음이면 하나만 소리 난다는 것을 낱말 두 개로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X08','kor',1,'u2',ARRAY['K1-2-u2-C3']::text[],'뒤에 모음이 와도 받침 하나만 소리 낸다 (낡은→[나근], 읽어→[이거])','뒤 글자에 모음이 올 때 받침 하나가 넘어가는 것을 손으로 밀어 보이며 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X09','kor',1,'u2',ARRAY['K1-2-u2-C3']::text[],'ㅟ를 ㅣ나 ㅜ로 읽는다 (바퀴→[바키], 튀김→[티김])','입술을 동그랗게 모은 채 소리 내는지 거울로 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X10','kor',1,'u2',ARRAY['K1-2-u2-C4']::text[],'글의 첫 문장만 보고 하고 싶은 말을 정한다','「끝까지 읽고 제목과 까닭을 이으면 어떻게 되나요?」 다시 읽게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X11','kor',1,'u2',ARRAY['K1-2-u2-C4']::text[],'글 속의 한 가지 일이나 세부 내용을 하고 싶은 말로 고른다 (하은이는 날짜를 적어 둔다)','「그 문장은 글쓴이가 우리에게 하라는 말인가요, 있었던 일인가요?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X12','kor',1,'u2',ARRAY['K1-2-u2-C4']::text[],'글쓴이가 누구인지 모른다 — 글에 나오는 사람이나 제목을 글쓴이로 여긴다','글의 처음이나 끝에서 이름을 찾아 「이 사람이 이 글을 썼다」고 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X13','kor',1,'u2',ARRAY['K1-2-u2-C5']::text[],'인물의 생각을 인물의 말·행동이 아니라 내 생각으로 짐작한다','「그 인물이 무엇이라고 말했나요?」 말풍선을 다시 읽고 답 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X14','kor',1,'u2',ARRAY['K1-2-u2-C5']::text[],'물음이 하나면 답도 하나뿐이라고 여겨 다른 답을 틀렸다고 한다','나와 다른 답에 「왜 그렇게 생각했는지」 까닭을 물어보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X15','kor',1,'u2',ARRAY['K1-2-u2-C6']::text[],'낱말 카드 활동의 목적을 그림 그리기로 여긴다 (그림에만 힘쓰고 낱말을 소리대로 쓴다)','「카드에서 제일 중요한 것이 무엇인가요?」 낱말을 바르게 썼는지부터 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u2-X16','kor',1,'u2',ARRAY['K1-2-u2-C3','K1-2-u2-C6']::text[],'낱말의 뜻을 겉소리로 짐작한다 (닳다=달다, 굵다=굽다, 제날짜=제 날짜가 아닌 남의 날짜)','그 낱말이 나온 앞뒤 줄을 다시 읽고 무슨 뜻인지 장면으로 바꿔 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#1','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','도서관 알림판을 읽고 답하세요. 받침에 자음자가 두 개 있는 글자는 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":1,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"도서관 알림판을 읽고 답하세요. 받침에 자음자가 두 개 있는 글자는 어느 것인가요?","options":[{"t":"읽","correct":true},{"t":"책","mis":"K1-2-u2-X02"},{"t":"제","mis":"K1-2-u2-X02"}],"explanation":["「읽」의 받침은 ㄹ과 ㄱ, 자음자가 두 개예요.","「책」은 받침이 ㄱ 하나, 「제」는 받침이 없어요.","받침 자리를 손가락으로 짚고 자음자를 세어 봐요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 도서관 알림판을 읽고 답하세요. 받침에 자음자가 두 개 있는 글자는 어느 것인가요?","options":[{"t":"않","correct":true},{"t":"물","mis":"K1-2-u2-X02"},{"t":"건","mis":"K1-2-u2-X02"}],"explanation":["「않」의 받침은 ㄴ과 ㅎ, 자음자가 두 개예요.","「물」과 「건」은 받침이 하나예요.","받침 자리의 자음자를 세어 봐요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#2','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','「값」의 받침에는 자음자가 몇 개 있나요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「값」의 받침에는 자음자가 몇 개 있나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"K1-2-u2-X02"},{"t":"없어요","mis":"K1-2-u2-X02"}],"explanation":["「값」의 받침은 ㅂ과 ㅅ, 두 개예요.","받침이 하나인 글자와 헷갈리지 말아요.","글자를 첫소리·가운뎃소리·끝소리로 나눠 봐요."],"variant_rule":{"alt":[{"stem":"「흙」의 받침에는 자음자가 몇 개 있나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"K1-2-u2-X02"},{"t":"없어요","mis":"K1-2-u2-X02"}],"explanation":["「흙」의 받침은 ㄹ과 ㄱ, 두 개예요.","받침이 하나인 「흑」과 달라요.","끝소리 자리를 봐요."],"asset":null},{"stem":"「강」의 받침에는 자음자가 몇 개 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"K1-2-u2-X02"},{"t":"없어요","mis":"K1-2-u2-X02"}],"explanation":["「강」의 받침은 ㅇ 하나예요.","자음자가 두 개인 받침과 헷갈리지 말아요.","끝소리 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#3','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','다음 가운데 받침에 자음자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":3,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"다음 가운데 받침에 자음자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"없다","correct":true},{"t":"산","mis":"K1-2-u2-X02"},{"t":"나무","mis":"K1-2-u2-X02"}],"explanation":["「없」의 받침은 ㅂ과 ㅅ이에요.","「산」은 받침이 하나, 「나무」는 받침이 없어요.","받침 자리를 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 받침에 자음자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"일곱","mis":"K1-2-u2-X02"},{"t":"아홉","mis":"K1-2-u2-X02"}],"explanation":["「덟」의 받침은 ㄹ과 ㅂ이에요.","「일곱」과 「아홉」은 받침이 하나씩이에요.","끝 글자를 봐요."],"asset":null},{"stem":"이번에는 다른 보기예요. 다음 가운데 받침에 자음자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"개","mis":"K1-2-u2-X02"},{"t":"소","mis":"K1-2-u2-X02"}],"explanation":["「닭」의 받침은 ㄹ과 ㄱ이에요.","「개」와 「소」는 받침이 없어요.","받침 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#4','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','받침에 주의하며 바르게 읽어야 하는 까닭은 무엇인가요?',ARRAY['K1-2-u2-X07']::text[],true,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"받침에 주의하며 바르게 읽어야 하는 까닭은 무엇인가요?","options":[{"t":"듣는 사람이 알아들을 수 있어서","correct":true},{"t":"글을 빨리 읽을 수 있어서","mis":"K1-2-u2-X07"},{"t":"글씨가 예뻐 보여서","mis":"K1-2-u2-X07"}],"explanation":["바르게 읽어야 듣는 사람이 뜻을 알아들어요.","빨리 읽기나 글씨 모양과는 상관없어요.","친구에게 알림판을 읽어 준다고 생각해 봐요."],"variant_rule":{"alt":[{"stem":"낱말을 정확하게 읽으면 좋은 점은 무엇인가요?","options":[{"t":"듣는 사람에게 뜻이 바르게 전해져요","correct":true},{"t":"책을 안 읽어도 돼요","mis":"K1-2-u2-X07"},{"t":"글자가 커져요","mis":"K1-2-u2-X07"}],"explanation":["바르게 읽어야 뜻이 그대로 전해져요.","책을 안 읽거나 글자가 커지는 것과는 상관없어요.","알림판을 읽어 주는 나를 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#5','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','도서관 알림판을 읽고 답하세요. 알림판 글을 쓴 사람이 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X10','K1-2-u2-X11']::text[],false,'{"seq":5,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"도서관 알림판을 읽고 답하세요. 알림판 글을 쓴 사람이 하고 싶은 말은 무엇인가요?","options":[{"t":"도서관을 조용히 함께 쓰자","correct":true},{"t":"책상 위에 물건을 많이 올려 두자","mis":"K1-2-u2-X10"},{"t":"도서관에서 큰 소리로 읽자","mis":"K1-2-u2-X11"}],"explanation":["책을 제자리에, 물건은 두지 않기, 목소리는 작게 — 다 함께 조용히 쓰자는 말이에요.","물건을 올려 두거나 큰 소리를 내는 것은 반대 말이에요.","세 줄을 다 읽고 하나로 모아요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#6','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C1',2,'mc','auto','다음 낱말 가운데 받침에 자음자가 두 개인 글자가 없는 것은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":6,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"다음 낱말 가운데 받침에 자음자가 두 개인 글자가 없는 것은 어느 것인가요?","options":[{"t":"강물","correct":true},{"t":"읽다","mis":"K1-2-u2-X02"},{"t":"값","mis":"K1-2-u2-X02"}],"explanation":["「강」과 「물」은 받침이 ㅇ·ㄹ 하나씩이에요.","「읽」과 「값」은 받침에 자음자가 두 개예요.","받침 자리의 자음자를 세어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 낱말 가운데 받침에 자음자가 두 개인 글자가 없는 것은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"넓다","mis":"K1-2-u2-X02"},{"t":"닭","mis":"K1-2-u2-X02"}],"explanation":["「산」은 받침이 ㄴ 하나예요.","「넓」과 「닭」은 받침에 자음자가 두 개예요.","받침 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#7','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C6',2,'match','auto','낱말과 그 낱말의 받침 자음자 수를 선으로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 받침 자음자 수를 선으로 이어 보세요.","pairs":[{"l":"읽다","r":"2개"},{"l":"산","r":"1개"},{"l":"나무","r":"없음"}],"mis":"K1-2-u2-X02","explanation":["「읽」은 ㄹ과 ㄱ 두 개예요.","「산」은 ㄴ 하나, 「나무」는 받침이 없어요.","받침 자리를 하나씩 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말의 받침 자음자 수를 선으로 이어 보세요.","pairs":[{"l":"값","r":"2개"},{"l":"책","r":"1개"},{"l":"오리","r":"없음"}],"explanation":["「값」은 ㅂ과 ㅅ 두 개예요.","「책」은 ㄱ 하나, 「오리」는 받침이 없어요.","받침 자리를 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#8','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C3',2,'mc','auto','「읽다」를 소리 내어 읽으면 어떻게 들리나요?',ARRAY['K1-2-u2-X07','K1-2-u2-X08']::text[],true,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「읽다」를 소리 내어 읽으면 어떻게 들리나요?","options":[{"t":"[익따]","correct":true},{"t":"[일ㄱ다]","mis":"K1-2-u2-X07"},{"t":"[이다]","mis":"K1-2-u2-X08"}],"explanation":["받침이 두 개여도 뒤에 자음이 오면 소리는 하나만 나요.","두 소리를 다 내거나 받침을 빼고 읽으면 안 돼요.","입으로 읽어 보고 귀로 들어 봐요."],"variant_rule":{"alt":[{"stem":"「값」을 소리 내어 읽으면 어떻게 들리나요?","options":[{"t":"[갑]","correct":true},{"t":"[갑스]","mis":"K1-2-u2-X07"},{"t":"[가]","mis":"K1-2-u2-X08"}],"explanation":["낱말이 끝나면 겹받침 소리는 하나만 나요.","두 소리를 다 내거나 받침을 빼면 안 돼요.","소리 내어 읽어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#9','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C3',2,'ox','auto','받침에 자음자가 두 개 있으면 소리도 언제나 두 개가 나요.',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":9,"concept":"K1-2-u2-C3","difficulty":2,"kind":"ox","stem":"받침에 자음자가 두 개 있으면 소리도 언제나 두 개가 나요.","answer":"X","reason_options":[{"t":"뒤에 자음이 오거나 낱말이 끝나면 하나만 소리 나니까","correct":true},{"t":"받침 자음자 수와 소리 수는 언제나 같으니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["「읽다」는 [익따], 「값」은 [갑]처럼 하나만 소리 나요.","뒤에 모음이 올 때만 둘 다 소리 나요.","소리 내어 읽고 귀로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_basic#10','kor',1,2,'u2','L01','g1_2_kor_u2_L01_basic','lesson_basic','K1-2-u2-C4',3,'mc','auto','도서관 알림판을 읽고 답하세요. 「목소리는 작게, 걸음은 천천히.」를 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":10,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"도서관 알림판을 읽고 답하세요. 「목소리는 작게, 걸음은 천천히.」를 쓴 까닭은 무엇인가요?","options":[{"t":"다른 사람이 조용히 책을 읽을 수 있게 하려고","correct":true},{"t":"책을 빨리 찾게 하려고","mis":"K1-2-u2-X11"},{"t":"걸음을 많이 걷게 하려고","mis":"K1-2-u2-X11"}],"explanation":["도서관은 여럿이 조용히 책을 읽는 곳이에요.","책을 찾는 빠르기나 걸음 수와는 상관없어요.","앞의 두 줄과 이어서 생각해요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#1','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C6',2,'mc','auto','도서관 알림판을 읽고 답하세요. 받침에 자음자가 두 개 있는 글자는 모두 몇 개인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":1,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"도서관 알림판을 읽고 답하세요. 받침에 자음자가 두 개 있는 글자는 모두 몇 개인가요?","options":[{"t":"2개 (읽·않)","correct":true},{"t":"1개 (읽)","mis":"K1-2-u2-X02"},{"t":"3개 (읽·꽂·않)","mis":"K1-2-u2-X02"}],"explanation":["「읽」과 「않」 두 글자가 받침에 자음자가 두 개예요.","「꽂」의 받침은 ㅈ 하나예요.","한 글자씩 받침 자리를 봐요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#2','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C1',2,'mc','auto','글자 「맑」에서 끝소리 자리에 있는 것은 무엇인가요?',ARRAY['K1-2-u2-X03']::text[],true,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"글자 「맑」에서 끝소리 자리에 있는 것은 무엇인가요?","options":[{"t":"ㄺ","correct":true},{"t":"ㅁ","mis":"K1-2-u2-X03"},{"t":"ㅏ","mis":"K1-2-u2-X03"}],"explanation":["끝소리 자리에는 받침 ㄺ이 있어요.","ㅁ은 첫소리, ㅏ는 가운뎃소리예요.","글자를 세 조각으로 나눠 봐요."],"variant_rule":{"alt":[{"stem":"글자 「값」에서 첫소리 자리에 있는 것은 무엇인가요?","options":[{"t":"ㄱ","correct":true},{"t":"ㅄ","mis":"K1-2-u2-X03"},{"t":"ㅏ","mis":"K1-2-u2-X03"}],"explanation":["첫소리 자리에는 ㄱ이 있어요.","ㅄ은 끝소리, ㅏ는 가운뎃소리예요.","세 자리 이름을 붙여 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#3','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C3',3,'mc','auto','「읽다」를 [익따]라고 읽는 까닭은 무엇인가요?',ARRAY['K1-2-u2-X08','K1-2-u2-X07']::text[],false,'{"seq":3,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"「읽다」를 [익따]라고 읽는 까닭은 무엇인가요?","options":[{"t":"받침 뒤에 자음이 와서 받침 하나만 소리 나기 때문에","correct":true},{"t":"받침이 두 개면 언제나 하나만 소리 나기 때문에","mis":"K1-2-u2-X08"},{"t":"ㄹ은 원래 소리가 안 나기 때문에","mis":"K1-2-u2-X07"}],"explanation":["뒤에 자음 ㄷ이 오니 받침 하나만 소리 나요.","뒤에 모음이 오면 「읽어[일거]」처럼 둘 다 소리 나요.","뒤에 무엇이 오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#4','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C6',3,'error','auto','받침에 자음자가 두 개 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#5','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C4',3,'mc','auto','도서관 알림판을 읽고 답하세요. 「읽은 책은 제자리에 꽂아 주세요.」라고 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"도서관 알림판을 읽고 답하세요. 「읽은 책은 제자리에 꽂아 주세요.」라고 쓴 까닭은 무엇인가요?","options":[{"t":"다음 사람이 책을 쉽게 찾을 수 있게 하려고","correct":true},{"t":"책을 더 많이 읽게 하려고","mis":"K1-2-u2-X11"},{"t":"책상을 깨끗하게 하려고","mis":"K1-2-u2-X11"}],"explanation":["제자리에 있어야 다음 사람이 바로 찾아요.","읽는 양이나 책상과는 상관없는 줄이에요.","왜 그렇게 하라는지 떠올려요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#6','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C6',3,'ox','auto','받침에 자음자가 두 개 있는 글자는 교과서에만 있어요.',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":6,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"받침에 자음자가 두 개 있는 글자는 교과서에만 있어요.","answer":"X","reason_options":[{"t":"알림판·책·안내문 같은 둘레의 글에도 있으니까","correct":true},{"t":"우리가 쓰는 말에는 겹받침이 없으니까","mis":"K1-2-u2-X02"}],"mis":"K1-2-u2-X02","explanation":["도서관 알림판의 「읽은」·「않습니다」처럼 둘레 글에 많아요.","우리가 쓰는 말에도 「없다」·「값」처럼 가득해요.","둘레의 글을 한번 둘러봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#7','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C3',3,'mc','auto','「읽은 책」에서 「읽은」은 어떻게 소리 나나요?',ARRAY['K1-2-u2-X08','K1-2-u2-X07']::text[],false,'{"seq":7,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"「읽은 책」에서 「읽은」은 어떻게 소리 나나요?","options":[{"t":"[일근]","correct":true},{"t":"[이근]","mis":"K1-2-u2-X08"},{"t":"[익은]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 모음 ㅡ가 오니 ㄹ과 ㄱ이 둘 다 소리 나요.","받침을 빼거나 한 소리만 내면 안 돼요.","「읽다[익따]」와 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#8','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C1',4,'sa','auto','「없다」의 첫 글자 「없」의 받침을 쓰세요. (자음자 두 개)','{}'::text[],true,'{"seq":8,"concept":"K1-2-u2-C1","difficulty":4,"kind":"sa","stem":"「없다」의 첫 글자 「없」의 받침을 쓰세요. (자음자 두 개)","answer":["ㅄ","ㅂㅅ","ㅂ ㅅ","ㅂ,ㅅ","ㅂ·ㅅ","ㅂ과ㅅ"],"explanation":["「없」의 받침은 ㅂ과 ㅅ이에요.","소리는 [업]으로 하나만 나지만 받침은 두 개예요.","글자를 세 조각으로 떼어 봐요."],"variant_rule":{"alt":[{"stem":"「읽다」의 첫 글자 「읽」의 받침을 쓰세요. (자음자 두 개)","answer":["ㄺ","ㄹㄱ","ㄹ ㄱ","ㄹ,ㄱ","ㄹ·ㄱ","ㄹ과ㄱ"],"explanation":["「읽」의 받침은 ㄹ과 ㄱ이에요.","소리는 [익]으로 하나만 나지만 받침은 두 개예요.","끝소리 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#9','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C4',4,'essay','teacher','도서관 알림판을 읽고, 이 글을 쓴 사람이 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"도서관 알림판을 읽고, 이 글을 쓴 사람이 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 도서관을 조용히 함께 쓰자. / 다른 사람을 생각하며 도서관을 쓰자. — 세 줄을 하나로 모은 말이면 맞아요.","scoring_points":["세 줄을 다 읽고 모았는가","「함께·조용히」 같은 하나의 뜻으로 묶었는가","한 줄만 베끼지 않았는가"]},"explanation":["세 줄이 모두 「다른 사람을 생각하자」로 모여요.","한 줄만 옮겨 쓰면 하고 싶은 말이 아니에요.","세 줄을 읽고 공통점을 찾아요."],"asset":{"type":"passage","lines":["읽은 책은 제자리에 꽂아 주세요.","책상 위에 물건을 두지 않습니다.","목소리는 작게, 걸음은 천천히."],"title":"도서관 알림판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L01_challenge#10','kor',1,2,'u2','L01','g1_2_kor_u2_L01_challenge','lesson_challenge','K1-2-u2-C6',4,'essay','teacher','우리 교실이나 집에서 받침에 자음자가 두 개 있는 낱말을 두 개 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C6","difficulty":4,"kind":"essay","stem":"우리 교실이나 집에서 받침에 자음자가 두 개 있는 낱말을 두 개 찾아 쓰세요.","answer_guide":{"answer":"예: 값·읽다·없다·닭·흙·여덟·넓다 가운데 두 개 — 받침에 자음자가 두 개면 맞아요.","scoring_points":["두 낱말을 썼는가","두 낱말 모두 받침에 자음자가 두 개인가","받침을 바르게 썼는가"]},"explanation":["둘레의 글과 말에서 찾아요.","받침 자리에 자음자가 두 개인지 확인해요.","찾은 낱말은 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#1','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','같은 자음자가 겹쳐진 받침을 무엇이라고 하나요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],true,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"같은 자음자가 겹쳐진 받침을 무엇이라고 하나요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["ㄲ·ㅆ처럼 같은 자음자가 겹치면 쌍받침이에요.","겹받침은 서로 다른 자음자 두 개예요.","받침을 따로 써 보고 같은지 다른지 봐요."],"variant_rule":{"alt":[{"stem":"서로 다른 자음자 두 개로 된 받침을 무엇이라고 하나요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["ㄺ·ㅄ처럼 다른 자음자 두 개면 겹받침이에요.","쌍받침은 같은 자음자가 겹친 것이에요.","두 자음자가 같은지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#2','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','「낚」의 받침 ㄲ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],true,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「낚」의 받침 ㄲ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["ㄱ이 두 번 겹쳤으니 쌍받침이에요.","서로 다른 자음자가 아니라 겹받침이 아니에요.","받침만 따로 써 봐요."],"asset":{"type":"scene","icon":"낚","text":"받침 ㄲ"},"variant_rule":{"alt":[{"stem":"「닦다」의 받침 ㄲ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["같은 자음자 ㄱ이 겹쳤으니 쌍받침이에요.","다른 자음자 둘이 아니라 겹받침이 아니에요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"닦","text":"받침 ㄲ"}},{"stem":"「있다」의 받침 ㅆ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"끝소리가 아니에요","mis":"K1-2-u2-X03"}],"explanation":["같은 자음자 ㅅ이 겹쳤으니 쌍받침이에요.","겹받침은 다른 자음자 둘이에요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"있","text":"받침 ㅆ"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#3','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','「맑」의 받침 ㄺ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],true,'{"seq":3,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「맑」의 받침 ㄺ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["ㄹ과 ㄱ, 서로 다른 자음자 두 개라 겹받침이에요.","같은 자음자가 겹친 게 아니라 쌍받침이 아니에요.","받침의 두 자음자가 같은지 봐요."],"asset":{"type":"scene","icon":"맑","text":"받침 ㄺ"},"variant_rule":{"alt":[{"stem":"「값」의 받침 ㅄ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["ㅂ과 ㅅ, 다른 자음자 둘이라 겹받침이에요.","같은 자음자가 겹친 것이 아니에요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"값","text":"받침 ㅄ"}},{"stem":"「여덟」의 받침 ㄼ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["ㄹ과 ㅂ, 다른 자음자 둘이라 겹받침이에요.","쌍받침은 ㄲ·ㅆ처럼 같은 것이 겹친 거예요.","두 자음자를 견주어 봐요."],"asset":{"type":"scene","icon":"덟","text":"받침 ㄼ"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#4','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',1,'mc','auto','글자 「맑」은 세 자리로 나누어져요. 가운뎃소리는 무엇인가요?',ARRAY['K1-2-u2-X03']::text[],true,'{"seq":4,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"글자 「맑」은 세 자리로 나누어져요. 가운뎃소리는 무엇인가요?","options":[{"t":"ㅏ","correct":true},{"t":"ㅁ","mis":"K1-2-u2-X03"},{"t":"ㄺ","mis":"K1-2-u2-X03"}],"explanation":["가운뎃소리 자리에는 모음 ㅏ가 있어요.","ㅁ은 첫소리, ㄺ은 끝소리예요.","첫소리·가운뎃소리·끝소리 차례로 짚어요."],"asset":{"type":"scene","icon":"맑","text":"ㅁ · ㅏ · ㄺ"},"variant_rule":{"alt":[{"stem":"글자 「값」은 세 자리로 나누어져요. 끝소리는 무엇인가요?","options":[{"t":"ㅄ","correct":true},{"t":"ㄱ","mis":"K1-2-u2-X03"},{"t":"ㅏ","mis":"K1-2-u2-X03"}],"explanation":["끝소리 자리에는 받침 ㅄ이 있어요.","ㄱ은 첫소리, ㅏ는 가운뎃소리예요.","세 자리 차례로 짚어요."],"asset":{"type":"scene","icon":"값","text":"ㄱ · ㅏ · ㅄ"}},{"stem":"글자 「흙」은 세 자리로 나누어져요. 첫소리는 무엇인가요?","options":[{"t":"ㅎ","correct":true},{"t":"ㅡ","mis":"K1-2-u2-X03"},{"t":"ㄺ","mis":"K1-2-u2-X03"}],"explanation":["첫소리 자리에는 ㅎ이 있어요.","ㅡ는 가운뎃소리, ㄺ은 끝소리예요.","세 자리 차례로 짚어요."],"asset":{"type":"scene","icon":"흙","text":"ㅎ · ㅡ · ㄺ"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#5','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',2,'mc','auto','다음 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X02']::text[],true,'{"seq":5,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"넓다","correct":true},{"t":"낚다","mis":"K1-2-u2-X01"},{"t":"강","mis":"K1-2-u2-X02"}],"explanation":["「넓」의 받침 ㄼ은 서로 다른 자음자 두 개예요.","「낚」의 ㄲ은 쌍받침, 「강」의 ㅇ은 받침 하나예요.","받침을 떼어 같은지 다른지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"앉다","correct":true},{"t":"있다","mis":"K1-2-u2-X01"},{"t":"손","mis":"K1-2-u2-X02"}],"explanation":["「앉」의 받침 ㄵ은 다른 자음자 둘이에요.","「있」의 ㅆ은 쌍받침, 「손」은 받침이 하나예요.","받침을 떼어 봐요."],"asset":null},{"stem":"이번에는 다른 보기예요. 다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"굵다","correct":true},{"t":"볶다","mis":"K1-2-u2-X01"},{"t":"길","mis":"K1-2-u2-X02"}],"explanation":["「굵」의 받침 ㄺ은 다른 자음자 둘이에요.","「볶」의 ㄲ은 쌍받침, 「길」은 받침이 하나예요.","받침을 떼어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#6','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',2,'match','auto','낱말과 그 낱말의 받침을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"값","r":"ㅄ"},{"l":"읽다","r":"ㄺ"},{"l":"여덟","r":"ㄼ"}],"mis":"K1-2-u2-X05","explanation":["「값」은 ㅄ, 「읽」은 ㄺ이에요.","「덟」은 ㄼ이에요.","끝소리 자리를 하나씩 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"없다","r":"ㅄ"},{"l":"닭","r":"ㄺ"},{"l":"넓다","r":"ㄼ"}],"explanation":["「없」은 ㅄ, 「닭」은 ㄺ이에요.","「넓」은 ㄼ이에요.","받침을 떼어 봐요."]},{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"앉다","r":"ㄵ"},{"l":"많다","r":"ㄶ"},{"l":"흙","r":"ㄺ"}],"explanation":["「앉」은 ㄵ, 「많」은 ㄶ이에요.","「흙」은 ㄺ이에요.","받침을 떼어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
