INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#8','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',2,'mc','auto','두 낱말에 공통으로 들어갈 받침은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_basic#9','kor',1,2,'u2','L03','g1_2_kor_u2_L03_basic','lesson_basic','K1-2-u2-C1',2,'mc','auto','「여덟」의 끝 글자 「덟」을 만들려고 해요. ㄷ·ㅓ 다음에 빠진 것은 무엇인가요?',ARRAY['K1-2-u2-X04']::text[],true,'{"seq":9,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"「여덟」의 끝 글자 「덟」을 만들려고 해요. ㄷ·ㅓ 다음에 빠진 것은 무엇인가요?","options":[{"t":"ㄼ","correct":true},{"t":"ㄹ","mis":"K1-2-u2-X04"},{"t":"ㅂ","mis":"K1-2-u2-X04"}],"explanation":["ㄹ과 ㅂ이 함께 있는 겹받침 ㄼ이에요.","ㄹ 하나나 ㅂ 하나만 넣으면 다른 글자가 돼요.","받침 자리에 두 자음자를 다 넣어요."],"asset":{"type":"scene","icon":"ㄷ · ㅓ · ?","text":"덟"},"variant_rule":{"alt":[{"stem":"「흙」을 만들려고 해요. ㅎ·ㅡ 다음에 빠진 것은 무엇인가요?","options":[{"t":"ㄺ","correct":true},{"t":"ㄱ","mis":"K1-2-u2-X04"},{"t":"ㄹ","mis":"K1-2-u2-X04"}],"explanation":["ㄹ과 ㄱ이 함께 있는 겹받침 ㄺ이에요.","하나만 넣으면 「흑」이나 「흘」이 돼요.","받침 자리에 둘 다 넣어요."],"asset":{"type":"scene","icon":"ㅎ · ㅡ · ?","text":"흙"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
