INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#1','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',2,'mc','auto','글자 「없」의 세 자리를 바르게 나눈 것은 어느 것인가요?',ARRAY['K1-2-u2-X03']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":2,"kind":"mc","stem":"글자 「없」의 세 자리를 바르게 나눈 것은 어느 것인가요?","options":[{"t":"첫소리 ㅇ · 가운뎃소리 ㅓ · 끝소리 ㅄ","correct":true},{"t":"첫소리 ㅇ · 가운뎃소리 ㅓㅂ · 끝소리 ㅅ","mis":"K1-2-u2-X03"},{"t":"첫소리 ㅇㅓ · 끝소리 ㅄ","mis":"K1-2-u2-X03"}],"explanation":["ㅇ·ㅓ·ㅄ 세 조각이에요.","가운뎃소리는 모음 하나, 끝소리는 받침 자리 전체예요.","자리 이름을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#2','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',2,'mc','auto','문장에서 겹받침이 있는 글자는 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#3','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',3,'ox','auto','쌍받침과 겹받침은 모두 받침 자리에 자음자가 두 개 있어요.',ARRAY['K1-2-u2-X01']::text[],false,'{"seq":3,"concept":"K1-2-u2-C1","difficulty":3,"kind":"ox","stem":"쌍받침과 겹받침은 모두 받침 자리에 자음자가 두 개 있어요.","answer":"O","reason_options":[{"t":"둘 다 끝소리 자리에 자음자 두 개가 있으니까","correct":true},{"t":"쌍받침은 자음자가 하나뿐이니까","mis":"K1-2-u2-X01"}],"mis":"K1-2-u2-X01","explanation":["ㄲ·ㅆ도, ㄺ·ㅄ도 받침 자리에 자음자가 두 개예요.","다른 점은 같은 자음자인지 다른 자음자인지예요.","받침만 떼어 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#4','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',3,'error','auto','「밟다」의 받침을 ㅂㄹ이라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X05','K1-2-u2-X04','K1-2-u2-X02']::text[],true,'{"seq":4,"concept":"K1-2-u2-C1","difficulty":3,"kind":"error","stem":"「밟다」의 받침을 ㅂㄹ이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자 차례가 바뀌었어요 — 겹받침 ㄼ은 ㄹ 다음 ㅂ이에요","correct":true,"mis_target":"K1-2-u2-X05"},{"t":"겹받침은 자음자 하나만 써야 해요","mis":"K1-2-u2-X04"},{"t":"「밟」에는 받침이 없어요","mis":"K1-2-u2-X02"}],"explanation":["겹받침 ㄼ은 ㄹ이 먼저, ㅂ이 뒤예요.","자음자를 하나만 쓰면 다른 글자가 돼요.","바른 짝을 눈으로 확인해요."],"variant_rule":{"alt":[{"stem":"「값」의 받침을 ㅅㅂ이라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"자음자 차례가 바뀌었어요 — 겹받침 ㅄ은 ㅂ 다음 ㅅ이에요","correct":true,"mis_target":"K1-2-u2-X05"},{"t":"겹받침은 자음자 하나만 써야 해요","mis":"K1-2-u2-X04"},{"t":"「값」에는 받침이 없어요","mis":"K1-2-u2-X02"}],"explanation":["겹받침 ㅄ은 ㅂ이 먼저, ㅅ이 뒤예요.","하나만 쓰면 「갑」이 돼요.","바른 짝을 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#5','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',3,'mc','auto','다음 가운데 쌍받침과 겹받침이 각각 하나씩 들어 있는 짝은 어느 것인가요?',ARRAY['K1-2-u2-X01']::text[],false,'{"seq":5,"concept":"K1-2-u2-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 쌍받침과 겹받침이 각각 하나씩 들어 있는 짝은 어느 것인가요?","options":[{"t":"깎다 · 읽다","correct":true},{"t":"낚다 · 있다","mis":"K1-2-u2-X01"},{"t":"넓다 · 값","mis":"K1-2-u2-X01"}],"explanation":["「깎」의 ㄲ은 쌍받침, 「읽」의 ㄺ은 겹받침이에요.","「낚·있」은 둘 다 쌍받침, 「넓·값」은 둘 다 겹받침이에요.","한 낱말씩 받침 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#6','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',3,'match','auto','글자와 그 글자의 끝소리 이름을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C1","difficulty":3,"kind":"match","stem":"글자와 그 글자의 끝소리 이름을 선으로 이어 보세요.","pairs":[{"l":"볶","r":"쌍받침 ㄲ"},{"l":"삶","r":"겹받침 ㄻ"},{"l":"강","r":"받침 ㅇ 하나"}],"mis":"K1-2-u2-X01","explanation":["「볶」은 ㄱ이 겹친 쌍받침이에요.","「삶」은 ㄹ과 ㅁ 겹받침, 「강」은 받침 하나예요.","끝소리 자리를 떼어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#7','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',3,'mc','auto','「굵다」·「늙다」·「긁다」의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":7,"concept":"K1-2-u2-C1","difficulty":3,"kind":"mc","stem":"「굵다」·「늙다」·「긁다」의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"받침이 모두 겹받침 ㄺ이에요","correct":true},{"t":"받침이 모두 쌍받침이에요","mis":"K1-2-u2-X01"},{"t":"첫소리가 모두 같아요","mis":"K1-2-u2-X03"}],"explanation":["세 낱말 모두 끝소리 자리가 ㄺ이에요.","같은 자음자가 겹친 게 아니라 쌍받침이 아니에요.","첫소리는 ㄱ·ㄴ·ㄱ으로 다 같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#8','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',4,'sa','auto','「짧다」의 첫 글자 「짧」의 받침을 쓰세요. (자음자 두 개)','{}'::text[],true,'{"seq":8,"concept":"K1-2-u2-C1","difficulty":4,"kind":"sa","stem":"「짧다」의 첫 글자 「짧」의 받침을 쓰세요. (자음자 두 개)","answer":["ㄼ","ㄹㅂ","ㄹ ㅂ","ㄹ,ㅂ","ㄹ·ㅂ","ㄹ과ㅂ"],"explanation":["「짧」의 받침은 ㄹ과 ㅂ이에요.","소리는 [짤]로 하나만 나지만 받침은 두 개예요.","끝소리 자리를 떼어 봐요."],"variant_rule":{"alt":[{"stem":"「앉다」의 첫 글자 「앉」의 받침을 쓰세요. (자음자 두 개)","answer":["ㄵ","ㄴㅈ","ㄴ ㅈ","ㄴ,ㅈ","ㄴ·ㅈ","ㄴ과ㅈ"],"explanation":["「앉」의 받침은 ㄴ과 ㅈ이에요.","소리는 [안]으로 하나만 나요.","끝소리 자리를 떼어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#9','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',4,'essay','teacher','「닭」을 첫소리·가운뎃소리·끝소리 세 자리로 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C1","difficulty":4,"kind":"essay","stem":"「닭」을 첫소리·가운뎃소리·끝소리 세 자리로 나누어 쓰세요.","answer_guide":{"answer":"예: 첫소리 ㄷ · 가운뎃소리 ㅏ · 끝소리 ㄺ — 세 자리를 바르게 나누면 맞아요.","scoring_points":["첫소리 ㄷ을 썼는가","가운뎃소리 ㅏ를 썼는가","끝소리에 ㄺ 두 자음자를 다 썼는가"]},"explanation":["ㄷ·ㅏ·ㄺ 세 조각이에요.","끝소리 자리에는 자음자가 두 개 와도 한 자리예요.","자리 이름을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L03_challenge#10','kor',1,2,'u2','L03','g1_2_kor_u2_L03_challenge','lesson_challenge','K1-2-u2-C1',4,'essay','teacher','쌍받침과 겹받침은 무엇이 다른지 낱말 하나씩 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C1","difficulty":4,"kind":"essay","stem":"쌍받침과 겹받침은 무엇이 다른지 낱말 하나씩 예를 들어 쓰세요.","answer_guide":{"answer":"예: 쌍받침은 같은 자음자가 겹친 것(낚다), 겹받침은 다른 자음자 두 개(값). — 다른 점과 예가 맞으면 돼요.","scoring_points":["같은 자음자·다른 자음자로 다른 점을 말했는가","쌍받침 예가 맞는가","겹받침 예가 맞는가"]},"explanation":["쌍받침은 ㄲ·ㅆ처럼 같은 자음자가 겹친 것이에요.","겹받침은 ㄺ·ㅄ처럼 다른 자음자 둘이에요.","받침을 떼어 같은지 다른지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#1','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','그림에 어울리는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],true,'{"seq":1,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림에 어울리는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K1-2-u2-X04"},{"t":"갓","mis":"K1-2-u2-X05"}],"explanation":["물건을 살 때 내는 돈은 「값」이에요.","소리는 [갑]이지만 쓸 때는 ㅄ 받침이에요.","뜻을 먼저 떠올리고 받침을 정해요."],"asset":{"type":"scene","icon":"🪙🏷️","text":"물건을 살 때 내는 돈"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림에 어울리는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K1-2-u2-X04"},{"t":"달","mis":"K1-2-u2-X05"}],"explanation":["꼬꼬댁 우는 새는 「닭」이에요.","소리는 [닥]이지만 받침은 ㄺ이에요.","뜻을 떠올려요."],"asset":{"type":"scene","icon":"🐔","text":"꼬꼬댁 우는 새"}},{"stem":"이번에는 다른 보기예요. 그림에 어울리는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"흑","mis":"K1-2-u2-X04"},{"t":"흘","mis":"K1-2-u2-X05"}],"explanation":["땅에 있는 부드러운 것은 「흙」이에요.","소리는 [흑]이지만 받침은 ㄺ이에요.","뜻을 떠올려요."],"asset":{"type":"scene","icon":"🪴🌱","text":"화분에 담는 것"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#2','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'blank','auto','빈칸에 알맞은 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#3','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','「읽다」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04']::text[],true,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"「읽다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"익다","mis":"K1-2-u2-X04"},{"t":"일다","mis":"K1-2-u2-X04"}],"explanation":["책을 보는 것은 「읽다」, 받침은 ㄺ이에요.","「익다」·「일다」는 소리대로 받침 하나만 쓴 것이에요.","소리는 하나만 나도 쓸 때는 둘 다 써요."],"variant_rule":{"alt":[{"stem":"「넓다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"넓다","correct":true},{"t":"널다","mis":"K1-2-u2-X04"},{"t":"넙다","mis":"K1-2-u2-X04"}],"explanation":["넓은 것은 「넓다」, 받침은 ㄼ이에요.","「널다」·「넙다」는 받침 하나만 쓴 것이에요.","쓸 때는 둘 다 써요."],"asset":null},{"stem":"「앉다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"앉다","correct":true},{"t":"안다","mis":"K1-2-u2-X06"},{"t":"앚다","mis":"K1-2-u2-X04"}],"explanation":["의자에 앉는 것은 「앉다」, 받침은 ㄵ이에요.","「안다」는 품에 안는 것이라 다른 뜻이에요.","뜻을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#4','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',1,'mc','auto','소리와 글자가 다를 때는 어떻게 써야 하나요?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":4,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"소리와 글자가 다를 때는 어떻게 써야 하나요?","options":[{"t":"소리대로가 아니라 낱말대로 써요","correct":true},{"t":"들리는 소리대로 써요","mis":"K1-2-u2-X04"},{"t":"받침을 빼고 써요","mis":"K1-2-u2-X04"}],"explanation":["「값」은 [갑]으로 들려도 「값」이라고 써요.","소리대로 쓰면 뜻이 달라져요.","뜻을 먼저 떠올리고 받침을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#5','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'mc','auto','바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],true,'{"seq":5,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"바르게 쓴 문장은 어느 것인가요?","options":[{"t":"사과 값을 물었어요.","correct":true},{"t":"사과 갑을 물었어요.","mis":"K1-2-u2-X04"},{"t":"사과 갓을 물었어요.","mis":"K1-2-u2-X05"}],"explanation":["돈을 뜻하는 낱말은 「값」이에요.","「갑」은 소리대로, 「갓」은 받침을 잘못 쓴 것이에요.","뜻을 떠올리고 받침 ㅄ을 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"신발이 닳았어요.","correct":true},{"t":"신발이 달았어요.","mis":"K1-2-u2-X04"},{"t":"신발이 닭았어요.","mis":"K1-2-u2-X05"}],"explanation":["오래 써서 줄어든 것은 「닳다」예요.","「달았어요」는 소리대로, 「닭」은 다른 낱말이에요.","뜻을 떠올려요."],"asset":null},{"stem":"이번에는 다른 보기예요. 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"연필이 짧아요.","correct":true},{"t":"연필이 짤바요.","mis":"K1-2-u2-X04"},{"t":"연필이 짧바요.","mis":"K1-2-u2-X05"}],"explanation":["길이가 적은 것은 「짧다」예요.","「짤바요」는 소리대로, 「짧바요」는 받침을 두 번 썼어요.","낱말대로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#6','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'match','auto','낱말과 그 낱말을 소리 내어 읽을 때 나는 소리를 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u2-C2","difficulty":2,"kind":"match","stem":"낱말과 그 낱말을 소리 내어 읽을 때 나는 소리를 선으로 이어 보세요.","pairs":[{"l":"값","r":"[갑]"},{"l":"없다","r":"[업따]"},{"l":"넓다","r":"[널따]"}],"mis":"K1-2-u2-X07","explanation":["「값」은 [갑], 「없다」는 [업따]예요.","「넓다」는 [널따]예요 — 쓸 때는 받침 두 개, 소리는 하나예요.","소리 내어 읽어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말을 소리 내어 읽을 때 나는 소리를 선으로 이어 보세요.","pairs":[{"l":"읽다","r":"[익따]"},{"l":"짧다","r":"[짤따]"},{"l":"여덟","r":"[여덜]"}],"explanation":["「읽다」는 [익따], 「짧다」는 [짤따]예요.","「여덟」은 [여덜]이에요.","소리 내어 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#7','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'blank','auto','빈칸에 알맞은 받침을 골라 문장을 완성하세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#8','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'mc','auto','「업다」와 「없다」 가운데 「바람이 불지 않는다」는 뜻에 맞는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X06']::text[],true,'{"seq":8,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"「업다」와 「없다」 가운데 「바람이 불지 않는다」는 뜻에 맞는 낱말은 어느 것인가요?","options":[{"t":"없다","correct":true},{"t":"업다","mis":"K1-2-u2-X06"},{"t":"둘 다 같은 뜻이에요","mis":"K1-2-u2-X06"}],"explanation":["「없다」는 있지 않다는 뜻이에요.","「업다」는 동생을 등에 업는 것이라 뜻이 달라요.","소리가 같아도 뜻이 다르면 다른 낱말이에요."],"variant_rule":{"alt":[{"stem":"「갑」과 「값」 가운데 「물건을 살 때 내는 돈」이라는 뜻에 맞는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K1-2-u2-X06"},{"t":"둘 다 같은 뜻이에요","mis":"K1-2-u2-X06"}],"explanation":["돈은 「값」이에요.","「갑」은 물건을 담는 작은 상자예요.","뜻이 다르면 다른 낱말이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#9','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',2,'mc','auto','낱말대로 바르게 쓴 것은 모두 몇 개인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_basic#10','kor',1,2,'u2','L05','g1_2_kor_u2_L05_basic','lesson_basic','K1-2-u2-C2',3,'error','auto','「사과 갑을 물었어요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],true,'{"seq":10,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「사과 갑을 물었어요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「갑」 — 소리대로 썼어요. 돈을 뜻하는 낱말은 겹받침 ㅄ을 써서 「값」이에요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「사과」 — 받침을 빼먹었어요","mis":"K1-2-u2-X05"},{"t":"「물었어요」 — 「무렀어요」로 써야 해요","mis":"K1-2-u2-X04"}],"explanation":["소리는 [갑]이지만 「값」이라고 써요.","「사과」는 받침이 없는 낱말이고, 「물었어요」는 바르게 썼어요.","뜻을 떠올리고 받침을 정해요."],"variant_rule":{"alt":[{"stem":"「오늘은 바람이 업서요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「업서요」 — 소리대로 썼어요. 「없어요」라고 써요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「바람」 — 받침을 빼먹었어요","mis":"K1-2-u2-X05"},{"t":"「오늘」 — 「오눌」로 써야 해요","mis":"K1-2-u2-X04"}],"explanation":["[업써요]로 들려도 「없어요」예요.","「바람」과 「오늘」은 바르게 썼어요.","낱말대로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#1','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',2,'mc','auto','「값」을 「갑」이라고 쓰면 안 되는 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":1,"concept":"K1-2-u2-C2","difficulty":2,"kind":"mc","stem":"「값」을 「갑」이라고 쓰면 안 되는 까닭은 무엇인가요?","options":[{"t":"뜻이 달라지기 때문에","correct":true},{"t":"글자가 길어지기 때문에","mis":"K1-2-u2-X04"},{"t":"소리가 안 나기 때문에","mis":"K1-2-u2-X04"}],"explanation":["「갑」은 물건을 담는 상자라 뜻이 달라요.","글자 길이나 소리 때문이 아니에요.","낱말대로 써야 뜻이 그대로 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#2','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',2,'mc','auto','문장에서 잘못 쓴 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#3','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'ox','auto','「없다」와 「업다」는 소리가 같으니 아무거나 써도 돼요.',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":3,"kind":"ox","stem":"「없다」와 「업다」는 소리가 같으니 아무거나 써도 돼요.","answer":"X","reason_options":[{"t":"소리가 같아도 뜻이 다른 낱말이니까","correct":true},{"t":"받침만 다르면 같은 낱말이니까","mis":"K1-2-u2-X06"}],"mis":"K1-2-u2-X06","explanation":["「없다」는 있지 않다, 「업다」는 등에 업다예요.","뜻이 다르면 다른 낱말이에요.","뜻을 그림으로 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#4','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'error','auto','「동생이 그림책을 익고 잠들었어요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],true,'{"seq":4,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「동생이 그림책을 익고 잠들었어요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「익고」 — 소리대로 썼어요. 책을 보는 것은 「읽고」예요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「그림책」 — 「그림챙」으로 써야 해요","mis":"K1-2-u2-X05"},{"t":"「잠들었어요」 — 받침을 빼야 해요","mis":"K1-2-u2-X04"}],"explanation":["[익꼬]로 들려도 「읽고」라고 써요.","「그림책」과 「잠들었어요」는 바르게 썼어요.","낱말대로 써요."],"variant_rule":{"alt":[{"stem":"「연필이 너무 짤바서 못 써요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「짤바서」 — 소리대로 썼어요. 「짧아서」예요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「연필」 — 「연피」로 써야 해요","mis":"K1-2-u2-X05"},{"t":"「못」 — 받침을 빼야 해요","mis":"K1-2-u2-X04"}],"explanation":["[짤바서]로 들려도 「짧아서」예요.","「연필」과 「못」은 바르게 썼어요.","낱말대로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#5','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'mc','auto','다음 가운데 소리와 글자가 다른 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X04']::text[],true,'{"seq":5,"concept":"K1-2-u2-C2","difficulty":3,"kind":"mc","stem":"다음 가운데 소리와 글자가 다른 낱말은 어느 것인가요?","options":[{"t":"넓다","correct":true},{"t":"나무","mis":"K1-2-u2-X04"},{"t":"구름","mis":"K1-2-u2-X04"}],"explanation":["「넓다」는 [널따]로 소리 나서 소리와 글자가 달라요.","「나무」·「구름」은 소리대로 써도 같아요.","소리 내어 읽고 글자와 견주어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 소리와 글자가 다른 낱말은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"하나","mis":"K1-2-u2-X04"},{"t":"오리","mis":"K1-2-u2-X04"}],"explanation":["「여덟」은 [여덜]로 소리 나서 달라요.","「하나」·「오리」는 소리대로 써도 같아요.","읽고 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#6','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'match','auto','뜻과 바르게 쓴 낱말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C2","difficulty":3,"kind":"match","stem":"뜻과 바르게 쓴 낱말을 선으로 이어 보세요.","pairs":[{"l":"있지 않다","r":"없다"},{"l":"등에 업다","r":"업다"},{"l":"물건의 돈","r":"값"}],"mis":"K1-2-u2-X06","explanation":["있지 않은 것은 「없다」, 등에 태우는 것은 「업다」예요.","물건의 돈은 「값」이에요.","뜻을 먼저 보고 낱말을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#7','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',3,'mc','auto','낱말을 바르게 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":7,"concept":"K1-2-u2-C2","difficulty":3,"kind":"mc","stem":"낱말을 바르게 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻을 떠올린다 → 뜻에 맞는 받침을 생각한다 → 낱말대로 쓴다","correct":true},{"t":"소리를 듣는다 → 들리는 대로 쓴다","mis":"K1-2-u2-X04"},{"t":"받침을 뺀다 → 짧게 쓴다","mis":"K1-2-u2-X04"}],"explanation":["뜻 → 받침 → 낱말대로 차례예요.","들리는 대로 쓰면 「값」이 「갑」이 돼요.","자기주도 차시의 세 걸음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#8','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',4,'sa','auto','[갑]이라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (물건을 살 때 내는 돈)','{}'::text[],true,'{"seq":8,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"[갑]이라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (물건을 살 때 내는 돈)","answer":["값"],"explanation":["돈을 뜻하는 낱말은 「값」이에요.","소리는 [갑]이지만 받침은 ㅄ이에요.","뜻을 떠올리고 겹받침을 써요."],"variant_rule":{"alt":[{"stem":"[업따]라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (있지 않다)","answer":["없다"],"explanation":["있지 않은 것은 「없다」예요.","소리는 [업따]지만 받침은 ㅄ이에요.","뜻을 떠올려요."],"asset":null},{"stem":"[익따]라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (책을 보다)","answer":["읽다"],"explanation":["책을 보는 것은 「읽다」예요.","소리는 [익따]지만 받침은 ㄺ이에요.","뜻을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#9','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',4,'essay','teacher','「값 · 없다 · 짧다」 가운데 하나를 골라 그 낱말이 들어간 문장을 바르게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C2","difficulty":4,"kind":"essay","stem":"「값 · 없다 · 짧다」 가운데 하나를 골라 그 낱말이 들어간 문장을 바르게 쓰세요.","answer_guide":{"answer":"예: 사과 값이 얼마예요? / 오늘은 숙제가 없다. / 연필이 짧다. — 고른 낱말의 받침을 바르게 쓰면 맞아요.","scoring_points":["고른 낱말이 문장에 들어 있는가","겹받침을 바르게 썼는가","문장의 뜻이 자연스러운가"]},"explanation":["낱말의 뜻에 맞는 문장을 지어요.","받침을 소리대로 쓰지 않았는지 확인해요.","다 쓰고 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L05_challenge#10','kor',1,2,'u2','L05','g1_2_kor_u2_L05_challenge','lesson_challenge','K1-2-u2-C2',4,'essay','teacher','「국물이 말가요.」에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 왜 그렇게 쓰는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C2","difficulty":4,"kind":"essay","stem":"「국물이 말가요.」에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 왜 그렇게 쓰는지 쓰세요.","answer_guide":{"answer":"예: 말가요 → 맑아요. 소리는 [말가요]지만 「맑다」의 받침 ㄺ을 그대로 써야 해요. — 고친 낱말과 까닭이 맞으면 돼요.","scoring_points":["「맑아요」로 고쳤는가","소리대로가 아니라 낱말대로 쓴다는 까닭을 말했는가","받침 ㄺ을 바르게 썼는가"]},"explanation":["흐리지 않고 환한 것은 「맑다」예요.","뒤에 모음이 와서 [말가요]로 들리지만 쓸 때는 「맑아요」예요.","낱말대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#1','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','「낡은 우산」을 읽고 답하세요. 「낡은」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08','K1-2-u2-X07']::text[],true,'{"seq":1,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 「낡은」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[날근]","correct":true},{"t":"[나근]","mis":"K1-2-u2-X08"},{"t":"[낙은]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 모음이 오니 ㄹ과 ㄱ이 둘 다 소리 나서 [날근]이에요.","받침 하나를 빼거나 글자를 따로 읽으면 안 돼요.","「낡」 뒤에 무엇이 오는지 봐요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"},"variant_rule":{"alt":[{"stem":"「낡은 우산」을 읽고 답하세요. 「얇았어요」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[얄바써요]","correct":true},{"t":"[야바써요]","mis":"K1-2-u2-X08"},{"t":"[얍아써요]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 모음이 오니 ㄹ과 ㅂ이 둘 다 소리 나요.","받침 하나를 빼면 안 돼요.","「얇」 뒤에 오는 것을 봐요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#2','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','「넓고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X07']::text[],true,'{"seq":2,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「넓고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[널꼬]","correct":true},{"t":"[널브고]","mis":"K1-2-u2-X07"},{"t":"[넙꼬]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 자음 ㄱ이 오니 받침 하나만 소리 나서 [널꼬]예요.","두 소리를 다 내면 안 돼요.","뒤에 무엇이 오는지 봐요."],"variant_rule":{"alt":[{"stem":"「짧고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[짤꼬]","correct":true},{"t":"[짤브고]","mis":"K1-2-u2-X07"},{"t":"[짭꼬]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 자음이 오니 하나만 소리 나서 [짤꼬]예요.","두 소리를 다 내면 안 돼요.","뒤에 오는 것을 봐요."],"asset":null},{"stem":"「앉고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[안꼬]","correct":true},{"t":"[안즈고]","mis":"K1-2-u2-X07"},{"t":"[아꼬]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 자음이 오니 하나만 소리 나서 [안꼬]예요.","두 소리를 다 내거나 받침을 빼면 안 돼요.","뒤에 오는 것을 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#3','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','겹받침 뒤에 모음이 오면 소리는 어떻게 나나요?',ARRAY['K1-2-u2-X08']::text[],true,'{"seq":3,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"겹받침 뒤에 모음이 오면 소리는 어떻게 나나요?","options":[{"t":"두 자음이 다 소리 나요","correct":true},{"t":"하나만 소리 나요","mis":"K1-2-u2-X08"},{"t":"소리가 안 나요","mis":"K1-2-u2-X08"}],"explanation":["「낡은[날근]」처럼 둘 다 소리 나요.","자음이 오거나 낱말이 끝날 때만 하나만 나요.","「읽어」를 소리 내어 봐요."],"variant_rule":{"alt":[{"stem":"겹받침 뒤에 자음이 오거나 낱말이 끝나면 소리는 어떻게 나나요?","options":[{"t":"하나만 소리 나요","correct":true},{"t":"두 자음이 다 소리 나요","mis":"K1-2-u2-X07"},{"t":"소리가 안 나요","mis":"K1-2-u2-X07"}],"explanation":["「넓고[널꼬]」·「값[갑]」처럼 하나만 나요.","모음이 올 때만 둘 다 나요.","「값」을 소리 내어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#4','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',1,'mc','auto','「낡은 우산」을 읽고 답하세요. 「닳다」는 무슨 뜻인가요?',ARRAY['K1-2-u2-X16']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 「닳다」는 무슨 뜻인가요?","options":[{"t":"오래 써서 조금씩 줄어들다","correct":true},{"t":"물에 잠기다","mis":"K1-2-u2-X16"},{"t":"아주 무겁다","mis":"K1-2-u2-X16"}],"explanation":["손잡이가 닳았다는 것은 오래 써서 줄어들었다는 뜻이에요.","물이나 무게와는 상관없어요.","낱말이 나온 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#5','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',2,'mc','auto','「낡은 우산」을 읽고 답하세요. 유찬이가 찾은 우산은 어떠했나요?',ARRAY['K1-2-u2-X16']::text[],true,'{"seq":5,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 유찬이가 찾은 우산은 어떠했나요?","options":[{"t":"손잡이가 닳고 천도 얇았어요","correct":true},{"t":"새것이라 반짝였어요","mis":"K1-2-u2-X16"},{"t":"아주 크고 무거웠어요","mis":"K1-2-u2-X16"}],"explanation":["셋째 줄에 우산의 모습이 있어요.","새것이나 무거운 우산이 아니에요.","둘째·셋째 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"},"variant_rule":{"alt":[{"stem":"「낡은 우산」을 읽고 답하세요. 우산 속은 어떠했나요?","options":[{"t":"넓고 포근했어요","correct":true},{"t":"좁고 추웠어요","mis":"K1-2-u2-X16"},{"t":"비가 새어 들어왔어요","mis":"K1-2-u2-X16"}],"explanation":["다섯째 줄에 우산 속 모습이 있어요.","좁거나 비가 새지 않았어요.","다섯째 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#6','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',2,'match','auto','낱말과 그 낱말의 소리를 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u2-C3","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 소리를 선으로 이어 보세요.","pairs":[{"l":"낡은","r":"[날근]"},{"l":"넓고","r":"[널꼬]"},{"l":"값","r":"[갑]"}],"mis":"K1-2-u2-X07","explanation":["「낡은」은 모음 앞이라 둘 다, 「넓고」는 자음 앞이라 하나만 소리 나요.","「값」은 낱말 끝이라 [갑]이에요.","뒤에 무엇이 오는지 하나씩 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말의 소리를 선으로 이어 보세요.","pairs":[{"l":"읽어","r":"[일거]"},{"l":"읽다","r":"[익따]"},{"l":"여덟","r":"[여덜]"}],"explanation":["「읽어」는 모음 앞이라 둘 다 소리 나요.","「읽다」·「여덟」은 하나만 나요.","뒤에 오는 것을 봐요."]},{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말의 소리를 선으로 이어 보세요.","pairs":[{"l":"앉아","r":"[안자]"},{"l":"앉고","r":"[안꼬]"},{"l":"닭","r":"[닥]"}],"explanation":["「앉아」는 모음 앞이라 둘 다 소리 나요.","「앉고」·「닭」은 하나만 나요.","뒤에 오는 것을 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#7','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',2,'mc','auto','「흙이」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08']::text[],true,'{"seq":7,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「흙이」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[흘기]","correct":true},{"t":"[흐기]","mis":"K1-2-u2-X08"},{"t":"[흑이]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음 ㅣ가 오니 ㄹ과 ㄱ이 둘 다 소리 나요.","받침 하나만 내거나 글자를 따로 읽으면 안 돼요.","「흙 속에[흑쏘게]」와 견주어 봐요."],"variant_rule":{"alt":[{"stem":"「읽어」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[일거]","correct":true},{"t":"[이거]","mis":"K1-2-u2-X08"},{"t":"[익어]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 오니 둘 다 소리 나서 [일거]예요.","「읽다[익따]」와 달라요.","뒤에 오는 것을 봐요."],"asset":null},{"stem":"「닭이」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[달기]","correct":true},{"t":"[다기]","mis":"K1-2-u2-X08"},{"t":"[닥이]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 오니 둘 다 소리 나서 [달기]예요.","「닭[닥]」과 달라요.","뒤에 오는 것을 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#8','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',2,'ox','auto','「값」은 낱말이 끝나니 [갑]으로 읽어요.',ARRAY['K1-2-u2-X07']::text[],true,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":2,"kind":"ox","stem":"「값」은 낱말이 끝나니 [갑]으로 읽어요.","answer":"O","reason_options":[{"t":"낱말 끝에서는 겹받침 소리가 하나만 나니까","correct":true},{"t":"받침이 둘이면 [갑스]로 둘 다 읽어야 하니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["낱말 끝에서는 하나만 소리 나요.","[갑스]처럼 둘 다 내면 틀려요.","「값을[갑쓸]」과 「값[갑]」을 견주어 봐요."],"variant_rule":{"alt":[{"stem":"「여덟」은 낱말이 끝나니 [여덜]로 읽어요.","answer":"O","reason_options":[{"t":"낱말 끝에서는 겹받침 소리가 하나만 나니까","correct":true},{"t":"받침이 둘이면 [여덜브]로 둘 다 읽어야 하니까","mis":"K1-2-u2-X07"}],"explanation":["낱말 끝에서는 하나만 소리 나요.","둘 다 내면 틀려요.","소리 내어 읽어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#9','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','「낡은 우산」을 읽고 답하세요. 다음 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":9,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"낡은","correct":true},{"t":"우산","mis":"K1-2-u2-X02"},{"t":"손잡이","mis":"K1-2-u2-X02"}],"explanation":["「낡」의 받침은 ㄹ과 ㄱ이에요.","「산」·「손」·「잡」은 받침이 하나예요.","받침 자리에 자음자가 두 개인지 봐요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「낡은 우산」을 읽고 답하세요. 다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"넓고","correct":true},{"t":"포근","mis":"K1-2-u2-X02"},{"t":"창고","mis":"K1-2-u2-X02"}],"explanation":["「넓」의 받침은 ㄹ과 ㅂ이에요.","「근」은 받침 하나, 「창고」의 「고」는 받침이 없어요.","받침 자리를 봐요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_basic#10','kor',1,2,'u2','L07','g1_2_kor_u2_L07_basic','lesson_basic','K1-2-u2-C3',3,'mc','auto','「넓고」는 [널꼬], 「넓은」은 [널븐]으로 소리가 달라요. 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":10,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"「넓고」는 [널꼬], 「넓은」은 [널븐]으로 소리가 달라요. 그 까닭은 무엇인가요?","options":[{"t":"뒤에 자음이 오면 하나만, 모음이 오면 둘 다 소리 나기 때문에","correct":true},{"t":"두 낱말의 뜻이 다르기 때문에","mis":"K1-2-u2-X07"},{"t":"「넓」의 받침이 서로 다르기 때문에","mis":"K1-2-u2-X07"}],"explanation":["「넓」 뒤에 ㄱ이 오면 하나만, ㅡ가 오면 둘 다 소리 나요.","뜻이나 받침은 같아요.","뒤에 무엇이 오는지가 소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#1','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',2,'mc','auto','「낡은 우산」을 읽고 답하세요. 「얇았어요」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08','K1-2-u2-X07']::text[],false,'{"seq":1,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 「얇았어요」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[얄바써요]","correct":true},{"t":"[야바써요]","mis":"K1-2-u2-X08"},{"t":"[얍아써요]","mis":"K1-2-u2-X07"}],"explanation":["뒤에 모음이 오니 ㄹ과 ㅂ이 둘 다 소리 나요.","받침 하나를 빼거나 따로 읽으면 안 돼요.","「얇」 뒤에 오는 것을 봐요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#2','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',2,'mc','auto','「낡은 우산」을 읽고 답하세요. 유찬이가 "괜찮아. 아직 쓸 수 있어." 하고 말한 우산은 무엇이 낡았나요?',ARRAY['K1-2-u2-X16']::text[],false,'{"seq":2,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 유찬이가 \"괜찮아. 아직 쓸 수 있어.\" 하고 말한 우산은 무엇이 낡았나요?","options":[{"t":"손잡이와 천","correct":true},{"t":"바퀴와 끈","mis":"K1-2-u2-X16"},{"t":"지붕과 문","mis":"K1-2-u2-X16"}],"explanation":["셋째 줄에 손잡이가 닳고 천이 얇다고 나와요.","바퀴나 지붕은 우산에 없어요.","셋째 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#3','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'mc','auto','다음 가운데 겹받침 두 소리가 다 나는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X07']::text[],true,'{"seq":3,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 겹받침 두 소리가 다 나는 낱말은 어느 것인가요?","options":[{"t":"앉아","correct":true},{"t":"앉다","mis":"K1-2-u2-X07"},{"t":"값","mis":"K1-2-u2-X07"}],"explanation":["「앉아」는 뒤에 모음이 와서 [안자]로 둘 다 나요.","「앉다」·「값」은 하나만 나요.","뒤에 오는 것을 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 겹받침 두 소리가 다 나는 낱말은 어느 것인가요?","options":[{"t":"굵어","correct":true},{"t":"굵다","mis":"K1-2-u2-X07"},{"t":"닭","mis":"K1-2-u2-X07"}],"explanation":["「굵어」는 뒤에 모음이 와서 [굴거]로 둘 다 나요.","「굵다」·「닭」은 하나만 나요.","뒤에 오는 것을 봐요."],"asset":null},{"stem":"다음 가운데 겹받침 소리가 하나만 나는 낱말은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"읽어","mis":"K1-2-u2-X08"},{"t":"넓은","mis":"K1-2-u2-X08"}],"explanation":["「읽다」는 뒤에 자음이 와서 [익따]로 하나만 나요.","「읽어」·「넓은」은 둘 다 나요.","뒤에 오는 것을 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#4','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'error','auto','「닭이」를 [다기]라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u2-X08','K1-2-u2-X07','K1-2-u2-X02']::text[],true,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":3,"kind":"error","stem":"「닭이」를 [다기]라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"뒤에 모음이 오니 ㄹ과 ㄱ이 둘 다 소리 나서 [달기]예요","correct":true,"mis_target":"K1-2-u2-X08"},{"t":"[닥이]라고 글자마다 따로 읽어야 해요","mis":"K1-2-u2-X07"},{"t":"「닭」은 받침이 하나라 [다기]가 맞아요","mis":"K1-2-u2-X02"}],"explanation":["「닭이」는 [달기]예요.","받침 하나를 빼면 다른 낱말처럼 들려요.","뒤에 모음이 오면 둘 다 소리 나요."],"variant_rule":{"alt":[{"stem":"「굵어」를 [구거]라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"뒤에 모음이 오니 ㄹ과 ㄱ이 둘 다 소리 나서 [굴거]예요","correct":true,"mis_target":"K1-2-u2-X08"},{"t":"[국어]라고 글자마다 따로 읽어야 해요","mis":"K1-2-u2-X07"},{"t":"「굵」은 받침이 하나라 [구거]가 맞아요","mis":"K1-2-u2-X02"}],"explanation":["「굵어」는 [굴거]예요.","받침 하나를 빼면 안 돼요.","뒤에 모음이 오면 둘 다 소리 나요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#5','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'ox','auto','「읽어」와 「읽다」에서 「읽」의 소리는 서로 달라요.',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":5,"concept":"K1-2-u2-C3","difficulty":3,"kind":"ox","stem":"「읽어」와 「읽다」에서 「읽」의 소리는 서로 달라요.","answer":"O","reason_options":[{"t":"뒤에 오는 것이 모음인지 자음인지 다르니까","correct":true},{"t":"같은 글자면 소리도 언제나 같으니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["「읽어」는 [일거], 「읽다」는 [익따]예요.","같은 글자여도 뒤에 오는 것에 따라 소리가 달라져요.","두 낱말을 소리 내어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#6','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'match','auto','낱말과 그 낱말의 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C3","difficulty":3,"kind":"match","stem":"낱말과 그 낱말의 소리를 선으로 이어 보세요.","pairs":[{"l":"넓어","r":"[널버]"},{"l":"넓고","r":"[널꼬]"},{"l":"닭","r":"[닥]"}],"mis":"K1-2-u2-X07","explanation":["「넓어」는 모음 앞이라 둘 다 소리 나요.","「넓고」·「닭」은 하나만 나요.","뒤에 무엇이 오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#7','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',3,'mc','auto','「낡은 우산」을 읽고 답하세요. 「포근했어요」는 무슨 뜻인가요?',ARRAY['K1-2-u2-X16']::text[],false,'{"seq":7,"concept":"K1-2-u2-C3","difficulty":3,"kind":"mc","stem":"「낡은 우산」을 읽고 답하세요. 「포근했어요」는 무슨 뜻인가요?","options":[{"t":"따뜻하고 편안했어요","correct":true},{"t":"차갑고 딱딱했어요","mis":"K1-2-u2-X16"},{"t":"시끄러웠어요","mis":"K1-2-u2-X16"}],"explanation":["우산 속이 따뜻하고 편안했다는 뜻이에요.","차갑거나 시끄러운 것이 아니에요.","앞의 「넓고」와 이어서 읽어요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#8','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',4,'sa','auto','「읽어」를 소리 나는 대로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":4,"kind":"sa","stem":"「읽어」를 소리 나는 대로 쓰세요.","answer":["일거","[일거]","일 거"],"explanation":["뒤에 모음이 오니 ㄹ과 ㄱ이 둘 다 소리 나요.","[이거]나 [익어]가 아니에요.","소리 내어 읽고 들리는 대로 써요."],"variant_rule":{"alt":[{"stem":"「낡은」을 소리 나는 대로 쓰세요.","answer":["날근","[날근]","날 근"],"explanation":["뒤에 모음이 오니 둘 다 소리 나서 [날근]이에요.","[나근]이 아니에요.","들리는 대로 써요."],"asset":null},{"stem":"「값」을 소리 나는 대로 쓰세요.","answer":["갑","[갑]"],"explanation":["낱말 끝이라 하나만 소리 나서 [갑]이에요.","[갑스]가 아니에요.","들리는 대로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#9','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C3',4,'essay','teacher','「넓고」와 「넓어」를 소리 내어 읽으면 어떻게 다른지 쓰고, 왜 다른지 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C3","difficulty":4,"kind":"essay","stem":"「넓고」와 「넓어」를 소리 내어 읽으면 어떻게 다른지 쓰고, 왜 다른지 까닭을 쓰세요.","answer_guide":{"answer":"예: 「넓고」는 [널꼬], 「넓어」는 [널버]예요. 뒤에 자음이 오면 하나만, 모음이 오면 둘 다 소리 나기 때문이에요. — 두 소리와 까닭이 맞으면 돼요.","scoring_points":["[널꼬]·[널버] 두 소리를 바르게 썼는가","자음 앞·모음 앞으로 까닭을 말했는가","받침 자체가 다르다고 쓰지 않았는가"]},"explanation":["「넓고」는 하나만, 「넓어」는 둘 다 소리 나요.","받침은 같고 뒤에 오는 것이 달라요.","뒤에 무엇이 오는지로 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L07_challenge#10','kor',1,2,'u2','L07','g1_2_kor_u2_L07_challenge','lesson_challenge','K1-2-u2-C5',4,'essay','teacher','「낡은 우산」을 읽고, 유찬이가 "괜찮아. 아직 쓸 수 있어." 하고 말한 까닭을 짐작해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「낡은 우산」을 읽고, 유찬이가 \"괜찮아. 아직 쓸 수 있어.\" 하고 말한 까닭을 짐작해 쓰세요.","answer_guide":{"answer":"예: 낡았지만 비를 막을 수 있어서 / 우산 속이 넓고 포근해서. — 유찬이의 말과 뒤의 일을 이어 짐작하면 맞아요.","scoring_points":["유찬이가 한 말과 행동에서 까닭을 찾았는가","우산이 아직 쓸 만하다는 뜻이 들어 있는가","내 생각이 아니라 글의 내용으로 말했는가"]},"explanation":["낡았어도 쓸 수 있다는 유찬이의 생각이에요.","넷째·다섯째 줄을 이어 읽으면 까닭이 보여요.","인물의 말에서 생각을 짐작해요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#1','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','글을 쓴 사람을 무엇이라고 하나요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":1,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"글을 쓴 사람을 무엇이라고 하나요?","options":[{"t":"글쓴이","correct":true},{"t":"인물","mis":"K1-2-u2-X12"},{"t":"읽는 사람","mis":"K1-2-u2-X12"}],"explanation":["글을 쓴 사람이 글쓴이예요.","인물은 이야기에 나오는 사람, 읽는 사람은 우리예요.","글의 처음이나 끝에서 이름을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#2','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],true,'{"seq":2,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?","options":[{"t":"1학년 하은","correct":true},{"t":"도서관 선생님","mis":"K1-2-u2-X12"},{"t":"늦게 돌려준 친구","mis":"K1-2-u2-X12"}],"explanation":["첫 줄에 「1학년 하은」이라고 글쓴이가 적혀 있어요.","선생님이나 친구는 글에 나오는 사람이에요.","글의 처음을 봐요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"},"variant_rule":{"alt":[{"stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?","options":[{"t":"1학년 도윤","correct":true},{"t":"연필 주인","mis":"K1-2-u2-X12"},{"t":"선생님","mis":"K1-2-u2-X12"}],"explanation":["첫 줄에 「1학년 도윤」이라고 적혀 있어요.","연필 주인이나 선생님은 글쓴이가 아니에요.","글의 처음을 봐요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#3','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 이 글의 제목은 무엇인가요?',ARRAY['K1-2-u2-X10','K1-2-u2-X11']::text[],false,'{"seq":3,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 이 글의 제목은 무엇인가요?","options":[{"t":"빌린 책은 제날짜에 돌려주자","correct":true},{"t":"도서관에 가자","mis":"K1-2-u2-X10"},{"t":"하은이가 책을 빌렸다","mis":"K1-2-u2-X11"}],"explanation":["제목에 하고 싶은 말이 그대로 담겨 있어요.","「도서관에 가자」나 「책을 빌렸다」는 제목이 아니에요.","글 맨 위를 봐요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#4','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',1,'mc','auto','글쓴이가 하고 싶은 말이 담기기 쉬운 곳은 어디인가요?',ARRAY['K1-2-u2-X10']::text[],true,'{"seq":4,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"글쓴이가 하고 싶은 말이 담기기 쉬운 곳은 어디인가요?","options":[{"t":"제목","correct":true},{"t":"가장 긴 문장","mis":"K1-2-u2-X10"},{"t":"첫 글자","mis":"K1-2-u2-X10"}],"explanation":["하고 싶은 말은 제목에 담길 때가 많아요.","문장 길이나 첫 글자와는 상관없어요.","제목을 먼저 살펴봐요."],"variant_rule":{"alt":[{"stem":"글쓴이가 하고 싶은 말을 찾으려면 제목 다음에 무엇을 찾나요?","options":[{"t":"글을 쓴 까닭","correct":true},{"t":"가장 긴 문장","mis":"K1-2-u2-X10"},{"t":"글자 수","mis":"K1-2-u2-X10"}],"explanation":["제목과 쓴 까닭을 이으면 하고 싶은 말이 보여요.","문장 길이나 글자 수는 상관없어요.","왜 이 글을 썼을까 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#5','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?","options":[{"t":"늦게 돌려주면 기다리는 친구가 오래 기다려서","correct":true},{"t":"도서관이 넓다는 것을 알리려고","mis":"K1-2-u2-X11"},{"t":"책을 많이 빌리라고","mis":"K1-2-u2-X11"}],"explanation":["넷째·다섯째 줄에 까닭이 있어요.","도서관 크기나 빌리는 양과는 상관없어요.","「그런데」 뒤를 읽어요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#6','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":6,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"빌린 책은 제날짜에 돌려주자","correct":true},{"t":"책을 많이 빌리자","mis":"K1-2-u2-X11"},{"t":"하은이는 날짜를 적어 둔다","mis":"K1-2-u2-X11"}],"explanation":["제목과 쓴 까닭이 한곳으로 모여요.","「날짜를 적어 둔다」는 하은이가 한 일이에요.","제목과 마지막 줄을 이어요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#7','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'mc','auto','「화분에 물을 주고 가요」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],true,'{"seq":7,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「화분에 물을 주고 가요」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"당번은 잊지 말고 화분에 물을 주자","correct":true},{"t":"화분을 새로 사자","mis":"K1-2-u2-X11"},{"t":"잎이 마른다","mis":"K1-2-u2-X11"}],"explanation":["제목과 셋째 줄이 같은 말을 하고 있어요.","「잎이 마른다」는 물을 주어야 하는 까닭이에요.","제목과 마지막 줄을 이어요."],"asset":{"type":"passage","lines":["우리 반 화분은 사흘에 한 번 물을 줍니다.","물을 주지 않으면 잎이 마릅니다.","당번은 잊지 말고 물을 주고 갑시다."],"title":"화분에 물을 주고 가요"},"variant_rule":{"alt":[{"stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"학용품에 이름을 쓰자","correct":true},{"t":"연필을 많이 사자","mis":"K1-2-u2-X11"},{"t":"연필이 상자에 쌓인다","mis":"K1-2-u2-X11"}],"explanation":["제목과 마지막 줄이 같은 말이에요.","「상자에 쌓인다」는 있었던 일이에요.","제목과 마지막 줄을 이어요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#8','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'blank','auto','하고 싶은 말을 찾는 차례예요. 빈칸에 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#9','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',2,'ox','auto','글의 첫 문장만 읽으면 글쓴이가 하고 싶은 말을 알 수 있어요.',ARRAY['K1-2-u2-X10']::text[],false,'{"seq":9,"concept":"K1-2-u2-C4","difficulty":2,"kind":"ox","stem":"글의 첫 문장만 읽으면 글쓴이가 하고 싶은 말을 알 수 있어요.","answer":"X","reason_options":[{"t":"끝까지 읽고 제목과 쓴 까닭을 이어야 하니까","correct":true},{"t":"첫 문장에 하고 싶은 말이 다 있으니까","mis":"K1-2-u2-X10"}],"mis":"K1-2-u2-X10","explanation":["첫 문장만 보면 글 전체가 무슨 말인지 몰라요.","제목과 쓴 까닭을 이어서 찾아요.","「빌린 책…」 첫 줄은 글쓴이 이름뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_basic#10','kor',1,2,'u2','L09','g1_2_kor_u2_L09_basic','lesson_basic','K1-2-u2-C4',3,'mc','auto','「학용품에 이름을 쓰자」를 읽고 답하세요. 「잃어버린 연필은 그대로 상자에 쌓입니다」는 어떤 문장인가요?',ARRAY['K1-2-u2-X11','K1-2-u2-X12']::text[],false,'{"seq":10,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 「잃어버린 연필은 그대로 상자에 쌓입니다」는 어떤 문장인가요?","options":[{"t":"글쓴이가 본 일이에요 — 이름을 쓰자는 까닭이 돼요","correct":true},{"t":"글쓴이가 하고 싶은 말이에요","mis":"K1-2-u2-X11"},{"t":"이 글의 제목이에요","mis":"K1-2-u2-X12"}],"explanation":["연필이 쌓이는 것은 있었던 일이에요.","하고 싶은 말은 「이름을 쓰자」예요.","「하라는 말인가, 있었던 일인가」 물어봐요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#1','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',2,'mc','auto','「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":1,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?","options":[{"t":"다음 반이 공을 찾느라 시간이 가서","correct":true},{"t":"공이 비싸서","mis":"K1-2-u2-X11"},{"t":"운동장이 넓어서","mis":"K1-2-u2-X11"}],"explanation":["셋째 줄에 까닭이 있어요.","공의 값이나 운동장 크기와는 상관없어요.","「그런데」에 해당하는 줄을 찾아요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#2','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',2,'mc','auto','「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11','K1-2-u2-X10']::text[],false,'{"seq":2,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"공은 쓰고 나서 바구니에 넣자","correct":true},{"t":"체육 시간을 늘리자","mis":"K1-2-u2-X11"},{"t":"공을 운동장에 두자","mis":"K1-2-u2-X10"}],"explanation":["제목과 넷째 줄이 같은 말이에요.","시간을 늘리거나 공을 두자는 말은 없어요.","제목과 까닭을 이어요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#3','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'mc','auto','「공은 바구니에 넣자」를 읽고 답하세요. 「그래야 다음 반이 바로 쓸 수 있습니다」는 무엇을 말하나요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":3,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"「공은 바구니에 넣자」를 읽고 답하세요. 「그래야 다음 반이 바로 쓸 수 있습니다」는 무엇을 말하나요?","options":[{"t":"공을 바구니에 넣어야 하는 까닭","correct":true},{"t":"이 글의 제목","mis":"K1-2-u2-X12"},{"t":"글쓴이가 누구인지","mis":"K1-2-u2-X12"}],"explanation":["「그래야」 뒤에는 그렇게 해야 하는 까닭이 와요.","제목이나 글쓴이가 아니에요.","앞 줄과 이어서 읽어요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#4','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'error','auto','하고 싶은 말을 찾는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#5','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'mc','auto','「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이는 무엇을 보고 이 글을 썼나요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":3,"kind":"mc","stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이는 무엇을 보고 이 글을 썼나요?","options":[{"t":"이름이 없어 주인을 못 찾는 연필이 상자에 쌓이는 것","correct":true},{"t":"연필이 너무 짧아진 것","mis":"K1-2-u2-X11"},{"t":"친구들이 연필을 안 쓰는 것","mis":"K1-2-u2-X11"}],"explanation":["둘째~넷째 줄에 글쓴이가 본 일이 있어요.","연필 길이나 안 쓰는 것과는 상관없어요.","까닭이 되는 일을 찾아요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#6','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'match','auto','글과 그 글에서 글쓴이가 하고 싶은 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C4","difficulty":3,"kind":"match","stem":"글과 그 글에서 글쓴이가 하고 싶은 말을 선으로 이어 보세요.","pairs":[{"l":"도서관 알림판","r":"조용히 함께 쓰자"},{"l":"빌린 책은 제날짜에 돌려주자","r":"책을 제날짜에 돌려주자"},{"l":"화분에 물을 주고 가요","r":"당번은 물을 주자"}],"mis":"K1-2-u2-X11","explanation":["세 글 모두 제목에 하고 싶은 말이 담겨 있어요.","읽는 사람에게 하라는 말을 찾아요.","제목과 마지막 줄을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#7','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',3,'ox','auto','「빌린 책은 제날짜에 돌려주자」에서 「하은이는 날짜를 적어 둔다」가 글쓴이가 하고 싶은 말이에요.',ARRAY['K1-2-u2-X10']::text[],false,'{"seq":7,"concept":"K1-2-u2-C4","difficulty":3,"kind":"ox","stem":"「빌린 책은 제날짜에 돌려주자」에서 「하은이는 날짜를 적어 둔다」가 글쓴이가 하고 싶은 말이에요.","answer":"X","reason_options":[{"t":"그것은 하은이가 한 일이고 하고 싶은 말은 제날짜에 돌려주자니까","correct":true},{"t":"하은이 이야기가 제일 먼저 나오니까","mis":"K1-2-u2-X10"}],"mis":"K1-2-u2-X10","explanation":["날짜를 적어 두는 것은 하은이가 한 일이에요.","하고 싶은 말은 제목과 마지막 줄에 있어요.","「하라는 말인가, 한 일인가」 물어봐요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#8','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',4,'sa','auto','「학용품에 이름을 쓰자」에서 글쓴이가 하고 싶은 말이에요. 빈칸에 알맞은 낱말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#9','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',4,'essay','teacher','「공은 바구니에 넣자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「공은 바구니에 넣자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 다음 반이 바로 쓸 수 있게 공은 쓰고 나서 바구니에 넣자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「바구니에 넣자」는 말이 있는가","까닭(다음 반이 쓴다)을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","셋째·다섯째 줄이 까닭이에요.","둘을 「~니까 ~하자」로 이어요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L09_challenge#10','kor',1,2,'u2','L09','g1_2_kor_u2_L09_challenge','lesson_challenge','K1-2-u2-C4',4,'essay','teacher','우리 반 친구들에게 하고 싶은 말을 하나 정해 글의 제목을 짓고, 그렇게 말하고 싶은 까닭을 한 줄 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"우리 반 친구들에게 하고 싶은 말을 하나 정해 글의 제목을 짓고, 그렇게 말하고 싶은 까닭을 한 줄 쓰세요.","answer_guide":{"answer":"예: 제목 「복도에서는 걸어 다니자」 — 까닭: 뛰다가 부딪히면 다치니까. — 제목에 하고 싶은 말이 담기고 까닭이 있으면 맞아요.","scoring_points":["제목에 하고 싶은 말이 들어 있는가","까닭을 썼는가","제목과 까닭이 이어지는가"]},"explanation":["하고 싶은 말을 제목으로 만들어요.","왜 그렇게 하자는지 까닭을 붙여요.","「빌린 책은 제날짜에 돌려주자」가 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#1','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','이야기에 나오는 사람을 무엇이라고 하나요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":1,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"이야기에 나오는 사람을 무엇이라고 하나요?","options":[{"t":"인물","correct":true},{"t":"글쓴이","mis":"K1-2-u2-X13"},{"t":"제목","mis":"K1-2-u2-X13"}],"explanation":["이야기에 나오는 사람이 인물이에요.","글쓴이는 글을 쓴 사람, 제목은 글의 이름이에요.","말을 하거나 행동을 한 사람을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#2','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「기다려지는 때」를 읽고 답하세요. 연서가 사람들에게 물은 것은 무엇인가요?',ARRAY['K1-2-u2-X13']::text[],true,'{"seq":2,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「기다려지는 때」를 읽고 답하세요. 연서가 사람들에게 물은 것은 무엇인가요?","options":[{"t":"가장 기다려지는 때가 언제인지","correct":true},{"t":"가장 좋아하는 음식이 무엇인지","mis":"K1-2-u2-X13"},{"t":"가장 좋아하는 계절이 언제인지","mis":"K1-2-u2-X13"}],"explanation":["첫 줄에 연서의 물음이 있어요.","음식이나 계절을 묻지 않았어요.","첫 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"},"variant_rule":{"alt":[{"stem":"「제일 기다리는 날」을 읽고 답하세요. 지호가 식구들에게 물은 것은 무엇인가요?","options":[{"t":"제일 기다리는 날이 언제인지","correct":true},{"t":"제일 좋아하는 소리가 무엇인지","mis":"K1-2-u2-X13"},{"t":"제일 잘하는 일이 무엇인지","mis":"K1-2-u2-X13"}],"explanation":["첫 줄에 지호의 물음이 있어요.","소리나 잘하는 일을 묻지 않았어요.","첫 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#3','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','인물의 생각은 무엇을 보고 알 수 있나요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":3,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"인물의 생각은 무엇을 보고 알 수 있나요?","options":[{"t":"인물이 한 말과 행동","correct":true},{"t":"이야기의 길이","mis":"K1-2-u2-X13"},{"t":"인물의 수","mis":"K1-2-u2-X13"}],"explanation":["인물이 한 말과 행동에 생각이 담겨 있어요.","이야기 길이나 인물 수로는 알 수 없어요.","인물의 말풍선을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#4','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',1,'mc','auto','「기다려지는 때」를 읽고 답하세요. 조리사 선생님이 기다리는 때는 언제인가요?',ARRAY['K1-2-u2-X13']::text[],true,'{"seq":4,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「기다려지는 때」를 읽고 답하세요. 조리사 선생님이 기다리는 때는 언제인가요?","options":[{"t":"국이 알맞게 끓는 때","correct":true},{"t":"아이들이 책을 읽는 때","mis":"K1-2-u2-X13"},{"t":"운동장에 해가 드는 때","mis":"K1-2-u2-X13"}],"explanation":["둘째 줄에 조리사 선생님의 말이 있어요.","책 읽는 때는 도서관 선생님, 해가 드는 때는 체육 선생님이에요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"},"variant_rule":{"alt":[{"stem":"「기다려지는 때」를 읽고 답하세요. 체육 선생님이 기다리는 때는 언제인가요?","options":[{"t":"운동장에 해가 드는 때","correct":true},{"t":"국이 알맞게 끓는 때","mis":"K1-2-u2-X13"},{"t":"아이들이 책을 읽는 때","mis":"K1-2-u2-X13"}],"explanation":["넷째 줄에 체육 선생님의 말이 있어요.","국은 조리사 선생님, 책은 도서관 선생님이에요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#5','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'match','auto','「기다려지는 때」에서 인물과 그 인물이 말한 때를 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"「기다려지는 때」에서 인물과 그 인물이 말한 때를 선으로 이어 보세요.","pairs":[{"l":"조리사 선생님","r":"국이 끓는 때"},{"l":"도서관 선생님","r":"책을 읽는 때"},{"l":"체육 선생님","r":"해가 드는 때"}],"mis":"K1-2-u2-X13","explanation":["조리사 선생님은 국, 도서관 선생님은 책이에요.","체육 선생님은 운동장에 해가 드는 때예요.","인물마다 한 말을 다시 읽어요."],"variant_rule":{"alt":[{"stem":"「제일 기다리는 날」에서 인물과 그 인물이 말한 날을 선으로 이어 보세요.","pairs":[{"l":"할머니","r":"씨앗을 심는 날"},{"l":"아빠","r":"함께 밥을 먹는 일요일"},{"l":"동생","r":"생일"}],"explanation":["할머니는 텃밭, 아빠는 함께 먹는 밥이에요.","동생은 생일이에요.","인물마다 한 말을 다시 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#6','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','「기다려지는 때」를 읽고 답하세요. 조리사 선생님이 그렇게 말한 까닭은 무엇일까요?',ARRAY['K1-2-u2-X13']::text[],true,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"「기다려지는 때」를 읽고 답하세요. 조리사 선생님이 그렇게 말한 까닭은 무엇일까요?","options":[{"t":"날마다 하는 일이 국을 끓이는 일이라서","correct":true},{"t":"국을 싫어해서","mis":"K1-2-u2-X13"},{"t":"연서가 그렇게 말하라고 해서","mis":"K1-2-u2-X13"}],"explanation":["조리사 선생님은 날마다 국을 끓여요.","자기가 하는 일과 이어진 답이에요.","그 인물이 하는 일을 떠올려요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"},"variant_rule":{"alt":[{"stem":"「제일 기다리는 날」을 읽고 답하세요. 할머니가 그렇게 말한 까닭은 무엇일까요?","options":[{"t":"텃밭을 가꾸는 일을 좋아해서","correct":true},{"t":"케이크를 좋아해서","mis":"K1-2-u2-X13"},{"t":"일요일에 쉬어서","mis":"K1-2-u2-X13"}],"explanation":["할머니는 씨앗을 심는 날을 기다려요.","케이크는 동생, 일요일은 아빠예요.","그 인물의 말과 이어요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#7','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','「기다려지는 때」에서 세 사람의 답이 서로 다른 까닭은 무엇일까요?',ARRAY['K1-2-u2-X14','K1-2-u2-X13']::text[],false,'{"seq":7,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"「기다려지는 때」에서 세 사람의 답이 서로 다른 까닭은 무엇일까요?","options":[{"t":"사람마다 하는 일과 겪은 일이 달라서","correct":true},{"t":"한 사람만 바르게 답해서","mis":"K1-2-u2-X14"},{"t":"연서가 물음을 잘못 물어서","mis":"K1-2-u2-X13"}],"explanation":["하는 일이 다르니 기다리는 때도 달라요.","누가 맞고 틀린 것이 아니에요.","물음은 하나여도 답은 여럿일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#8','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'mc','auto','나와 답이 다른 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":8,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"나와 답이 다른 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 생각했는지 들려줄래?","correct":true},{"t":"네 답은 틀렸어.","mis":"K1-2-u2-X14"},{"t":"내 답으로 바꿔.","mis":"K1-2-u2-X14"}],"explanation":["까닭을 물어보면 생각이 더 넓어져요.","다르다고 틀린 것이 아니에요.","다른 답에도 그 사람의 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#9','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',2,'ox','auto','물음이 하나면 답도 언제나 하나뿐이에요.',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":9,"concept":"K1-2-u2-C5","difficulty":2,"kind":"ox","stem":"물음이 하나면 답도 언제나 하나뿐이에요.","answer":"X","reason_options":[{"t":"사람마다 겪은 일이 달라 답이 여럿일 수 있으니까","correct":true},{"t":"답은 언제나 하나로 정해져 있으니까","mis":"K1-2-u2-X14"}],"mis":"K1-2-u2-X14","explanation":["「기다려지는 때」에서 답이 세 가지였어요.","다른 답도 그 사람에게는 까닭이 있어요.","다섯째 줄 연서의 생각을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_basic#10','kor',1,2,'u2','L11','g1_2_kor_u2_L11_basic','lesson_basic','K1-2-u2-C5',3,'mc','auto','「제일 기다리는 날」을 읽고 답하세요. 아빠가 중요하게 여기는 것은 무엇일까요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":10,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"「제일 기다리는 날」을 읽고 답하세요. 아빠가 중요하게 여기는 것은 무엇일까요?","options":[{"t":"온 식구가 함께하는 것","correct":true},{"t":"맛있는 케이크","mis":"K1-2-u2-X13"},{"t":"텃밭의 씨앗","mis":"K1-2-u2-X13"}],"explanation":["아빠는 온 식구가 함께 밥을 먹는 날을 기다려요.","케이크는 동생, 씨앗은 할머니예요.","아빠의 말에서 생각을 짐작해요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#1','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',2,'mc','auto','「제일 기다리는 날」을 읽고 답하세요. 다음 가운데 이 이야기의 인물이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u2-X13']::text[],true,'{"seq":1,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"「제일 기다리는 날」을 읽고 답하세요. 다음 가운데 이 이야기의 인물이 아닌 것은 어느 것인가요?","options":[{"t":"텃밭","correct":true},{"t":"할머니","mis":"K1-2-u2-X13"},{"t":"동생","mis":"K1-2-u2-X13"}],"explanation":["텃밭은 곳이지 사람이 아니에요.","할머니와 동생은 말을 한 인물이에요.","말을 하거나 행동을 한 사람만 인물이에요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"},"variant_rule":{"alt":[{"stem":"「제일 좋아하는 소리」를 읽고 답하세요. 다음 가운데 이 이야기의 인물이 아닌 것은 어느 것인가요?","options":[{"t":"피아노","correct":true},{"t":"음악 선생님","mis":"K1-2-u2-X13"},{"t":"경비 아저씨","mis":"K1-2-u2-X13"}],"explanation":["피아노는 물건이지 사람이 아니에요.","음악 선생님과 경비 아저씨는 말을 한 인물이에요.","말을 한 사람만 인물이에요."],"asset":{"type":"passage","lines":["연우는 학교에서 어른들에게 물었어요. \"제일 좋아하는 소리는 뭐예요?\"","음악 선생님이 말했어요. \"피아노 소리지.\"","급식 선생님이 말했어요. \"맛있다고 말하는 소리예요.\"","경비 아저씨가 말했어요. \"아침에 인사하는 소리란다.\"","연우는 생각했어요. ''다 자기가 하는 일과 이어진 소리네.''"],"title":"제일 좋아하는 소리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#2','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',2,'mc','auto','「제일 좋아하는 소리」를 읽고 답하세요. 급식 선생님이 제일 좋아하는 소리는 무엇인가요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":2,"concept":"K1-2-u2-C5","difficulty":2,"kind":"mc","stem":"「제일 좋아하는 소리」를 읽고 답하세요. 급식 선생님이 제일 좋아하는 소리는 무엇인가요?","options":[{"t":"맛있다고 말하는 소리","correct":true},{"t":"피아노 소리","mis":"K1-2-u2-X13"},{"t":"아침에 인사하는 소리","mis":"K1-2-u2-X13"}],"explanation":["셋째 줄에 급식 선생님의 말이 있어요.","피아노는 음악 선생님, 인사는 경비 아저씨예요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["연우는 학교에서 어른들에게 물었어요. \"제일 좋아하는 소리는 뭐예요?\"","음악 선생님이 말했어요. \"피아노 소리지.\"","급식 선생님이 말했어요. \"맛있다고 말하는 소리예요.\"","경비 아저씨가 말했어요. \"아침에 인사하는 소리란다.\"","연우는 생각했어요. ''다 자기가 하는 일과 이어진 소리네.''"],"title":"제일 좋아하는 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#3','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'mc','auto','「제일 좋아하는 소리」를 읽고 답하세요. 연우가 알아낸 것은 무엇인가요?',ARRAY['K1-2-u2-X14','K1-2-u2-X13']::text[],false,'{"seq":3,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"「제일 좋아하는 소리」를 읽고 답하세요. 연우가 알아낸 것은 무엇인가요?","options":[{"t":"어른들이 좋아하는 소리는 자기가 하는 일과 이어져 있다","correct":true},{"t":"좋아하는 소리는 한 가지뿐이다","mis":"K1-2-u2-X14"},{"t":"어른들은 소리를 좋아하지 않는다","mis":"K1-2-u2-X13"}],"explanation":["다섯째 줄에 연우의 생각이 있어요.","답이 셋이었으니 한 가지뿐이 아니에요.","마지막 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["연우는 학교에서 어른들에게 물었어요. \"제일 좋아하는 소리는 뭐예요?\"","음악 선생님이 말했어요. \"피아노 소리지.\"","급식 선생님이 말했어요. \"맛있다고 말하는 소리예요.\"","경비 아저씨가 말했어요. \"아침에 인사하는 소리란다.\"","연우는 생각했어요. ''다 자기가 하는 일과 이어진 소리네.''"],"title":"제일 좋아하는 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#4','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'match','auto','「제일 좋아하는 소리」에서 인물과 그 인물이 좋아하는 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"K1-2-u2-C5","difficulty":3,"kind":"match","stem":"「제일 좋아하는 소리」에서 인물과 그 인물이 좋아하는 소리를 선으로 이어 보세요.","pairs":[{"l":"음악 선생님","r":"피아노 소리"},{"l":"급식 선생님","r":"맛있다고 말하는 소리"},{"l":"경비 아저씨","r":"인사하는 소리"}],"mis":"K1-2-u2-X13","explanation":["음악 선생님은 피아노, 급식 선생님은 맛있다는 말이에요.","경비 아저씨는 아침 인사 소리예요.","인물마다 한 말을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#5','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'error','auto','인물의 생각을 아는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#6','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'ox','auto','「제일 기다리는 날」에서 동생의 답은 어른들과 달라서 틀린 답이에요.',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":3,"kind":"ox","stem":"「제일 기다리는 날」에서 동생의 답은 어른들과 달라서 틀린 답이에요.","answer":"X","reason_options":[{"t":"동생에게는 동생의 까닭이 있으니까","correct":true},{"t":"어른의 답이 언제나 맞으니까","mis":"K1-2-u2-X14"}],"mis":"K1-2-u2-X14","explanation":["답이 다르다고 틀린 것이 아니에요.","동생은 생일을 기다릴 까닭이 있어요.","물음은 하나여도 답은 여럿이에요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#7','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',3,'mc','auto','「제일 기다리는 날」을 읽고 답하세요. 할머니가 중요하게 여기는 것은 무엇일까요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":7,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"「제일 기다리는 날」을 읽고 답하세요. 할머니가 중요하게 여기는 것은 무엇일까요?","options":[{"t":"텃밭에서 무엇을 기르는 것","correct":true},{"t":"케이크를 먹는 것","mis":"K1-2-u2-X13"},{"t":"일요일에 쉬는 것","mis":"K1-2-u2-X13"}],"explanation":["할머니는 씨앗을 심는 날을 기다려요.","케이크는 동생, 일요일은 아빠의 말이에요.","할머니의 말에서 생각을 짐작해요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#8','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',4,'sa','auto','「기다려지는 때」에서 도서관 선생님이 기다리는 때는 아이들이 무엇을 읽는 때인가요? 한 낱말로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u2-C5","difficulty":4,"kind":"sa","stem":"「기다려지는 때」에서 도서관 선생님이 기다리는 때는 아이들이 무엇을 읽는 때인가요? 한 낱말로 쓰세요.","answer":["책","책을읽는때","아이들이책을읽는때","책읽는때"],"explanation":["셋째 줄에 「아이들이 책을 읽는 때」라고 있어요.","국이나 해가 아니에요.","도서관 선생님의 말을 다시 읽어요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"},"variant_rule":{"alt":[{"stem":"「제일 좋아하는 소리」에서 음악 선생님이 제일 좋아하는 소리는 무엇 소리인가요? 한 낱말로 쓰세요.","answer":["피아노","피아노소리"],"explanation":["둘째 줄에 「피아노 소리」라고 있어요.","맛있다는 말이나 인사가 아니에요.","음악 선생님의 말을 다시 읽어요."],"asset":{"type":"passage","lines":["연우는 학교에서 어른들에게 물었어요. \"제일 좋아하는 소리는 뭐예요?\"","음악 선생님이 말했어요. \"피아노 소리지.\"","급식 선생님이 말했어요. \"맛있다고 말하는 소리예요.\"","경비 아저씨가 말했어요. \"아침에 인사하는 소리란다.\"","연우는 생각했어요. ''다 자기가 하는 일과 이어진 소리네.''"],"title":"제일 좋아하는 소리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#9','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',4,'essay','teacher','「제일 기다리는 날」을 읽고, 할머니의 말에서 할머니가 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「제일 기다리는 날」을 읽고, 할머니의 말에서 할머니가 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 할머니는 텃밭에서 무엇을 기르는 일을 좋아하고 소중하게 여긴다. — 할머니의 말(씨앗을 심는 날)과 이어서 짐작하면 맞아요.","scoring_points":["할머니의 말을 근거로 썼는가","텃밭·기르는 일과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["할머니는 씨앗을 심는 날을 기다린다고 말했어요.","그 말에서 텃밭 일을 소중히 여긴다는 생각이 보여요.","말과 행동에서 짐작해요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L11_challenge#10','kor',1,2,'u2','L11','g1_2_kor_u2_L11_challenge','lesson_challenge','K1-2-u2-C5',4,'essay','teacher','「제일 기다리는 날은 언제예요?」 물음에 내 답과 까닭을 쓰고, 친구의 답이 나와 다를 때 무엇이라고 말할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「제일 기다리는 날은 언제예요?」 물음에 내 답과 까닭을 쓰고, 친구의 답이 나와 다를 때 무엇이라고 말할지 쓰세요.","answer_guide":{"answer":"예: 나는 소풍 가는 날이에요. 친구들과 밖에서 놀 수 있어서요. 친구 답이 다르면 「왜 그렇게 생각했는지 들려줄래?」라고 말해요. — 내 답·까닭·다른 답을 대하는 말이 있으면 맞아요.","scoring_points":["내 답과 까닭을 썼는가","다른 답을 틀렸다고 하지 않았는가","까닭을 묻는 말을 썼는가"]},"explanation":["내 답에도 까닭을 붙여요.","다른 답은 틀린 것이 아니라 다른 것이에요.","까닭을 물어보면 생각이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#1','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":1,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"구름","mis":"K1-2-u2-X02"},{"t":"바다","mis":"K1-2-u2-X02"}],"explanation":["「값」에는 겹받침 ㅄ이 있어요.","「구름」은 받침이 하나, 「바다」는 받침이 없어요.","받침 자리에 자음자가 두 개인지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"개","mis":"K1-2-u2-X02"},{"t":"소","mis":"K1-2-u2-X02"}],"explanation":["「닭」에는 겹받침 ㄺ이 있어요.","「개」와 「소」는 받침이 없어요.","받침 자리를 봐요."],"asset":null},{"stem":"이번에는 다른 보기예요. 겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"돌","mis":"K1-2-u2-X02"},{"t":"물","mis":"K1-2-u2-X02"}],"explanation":["「흙」에는 겹받침 ㄺ이 있어요.","「돌」·「물」은 받침이 하나예요.","받침 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#2','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','낱말 카드 한 장에는 무엇을 담나요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":2,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"낱말 카드 한 장에는 무엇을 담나요?","options":[{"t":"그림 하나와 낱말 하나","correct":true},{"t":"그림만 여러 개","mis":"K1-2-u2-X15"},{"t":"긴 문장 하나","mis":"K1-2-u2-X15"}],"explanation":["그림 하나와 낱말 하나면 충분해요.","그림만 있거나 긴 문장은 카드가 아니에요.","가장 중요한 것은 낱말을 바르게 쓰는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#3','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','「짧다」 카드에 어울리는 그림은 어느 것인가요?',ARRAY['K1-2-u2-X16']::text[],true,'{"seq":3,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"「짧다」 카드에 어울리는 그림은 어느 것인가요?","options":[{"t":"몽당연필","correct":true},{"t":"넓은 바다","mis":"K1-2-u2-X16"},{"t":"밤하늘","mis":"K1-2-u2-X16"}],"explanation":["길이가 짧은 것을 그리면 좋아요.","넓은 바다나 밤하늘은 「짧다」와 어울리지 않아요.","낱말의 뜻을 먼저 떠올려요."],"variant_rule":{"alt":[{"stem":"「닭」 카드에 어울리는 그림은 어느 것인가요?","options":[{"t":"꼬꼬댁 우는 새","correct":true},{"t":"물고기","mis":"K1-2-u2-X16"},{"t":"나무","mis":"K1-2-u2-X16"}],"explanation":["꼬꼬댁 우는 새가 닭이에요.","물고기나 나무는 「닭」이 아니에요.","뜻을 떠올려요."],"asset":null},{"stem":"「넓다」 카드에 어울리는 그림은 어느 것인가요?","options":[{"t":"넓은 바다","correct":true},{"t":"몽당연필","mis":"K1-2-u2-X16"},{"t":"작은 콩","mis":"K1-2-u2-X16"}],"explanation":["넓은 바다가 「넓다」와 어울려요.","몽당연필이나 콩은 작아요.","뜻을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#4','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',1,'mc','auto','「흙 · 달 · 별」 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":4,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"「흙 · 달 · 별」 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"달","mis":"K1-2-u2-X02"},{"t":"별","mis":"K1-2-u2-X02"}],"explanation":["「흙」의 받침은 ㄹ과 ㄱ이에요.","「달」·「별」은 받침이 ㄹ 하나예요.","받침 자리의 자음자를 세어 봐요."],"variant_rule":{"alt":[{"stem":"「여덟 · 구름 · 별」 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"구름","mis":"K1-2-u2-X02"},{"t":"별","mis":"K1-2-u2-X02"}],"explanation":["「덟」의 받침은 ㄹ과 ㅂ이에요.","「름」·「별」은 받침이 하나예요.","받침 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#5','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','「씨앗을 심은 날」을 읽고 답하세요. 이 글에서 겹받침이 있는 낱말은 모두 몇 개인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":5,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「씨앗을 심은 날」을 읽고 답하세요. 이 글에서 겹받침이 있는 낱말은 모두 몇 개인가요?","options":[{"t":"3개 (흙·맑아·굵어)","correct":true},{"t":"1개 (흙)","mis":"K1-2-u2-X02"},{"t":"5개 (마당·흙·씨앗·맑아·굵어)","mis":"K1-2-u2-X02"}],"explanation":["「흙」·「맑」·「굵」의 받침은 모두 ㄺ이에요.","「마당」과 「씨앗」은 받침이 하나예요.","한 낱말씩 받침 자리를 봐요."],"asset":{"type":"passage","lines":["마당에 흙을 담고 씨앗을 심었어요.","물이 맑아 보였어요.","며칠 뒤 싹이 굵어졌어요."],"title":"씨앗을 심은 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#6','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'match','auto','낱말과 그 낱말 카드에 그릴 그림을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u2-C6","difficulty":2,"kind":"match","stem":"낱말과 그 낱말 카드에 그릴 그림을 선으로 이어 보세요.","pairs":[{"l":"닭","r":"꼬꼬댁 우는 새"},{"l":"읽다","r":"책을 보는 아이"},{"l":"흙","r":"마당의 땅"}],"mis":"K1-2-u2-X16","explanation":["닭은 새, 읽다는 책 보는 모습이에요.","흙은 마당의 땅이에요.","낱말의 뜻을 그림으로 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말 카드에 그릴 그림을 선으로 이어 보세요.","pairs":[{"l":"값","r":"물건과 돈"},{"l":"앉다","r":"의자에 앉은 아이"},{"l":"여덟","r":"8이라고 쓴 수"}],"explanation":["값은 돈, 앉다는 앉은 모습이에요.","여덟은 수 8이에요.","뜻을 그림으로 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#7','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','둘레의 글에서 겹받침 낱말을 찾은 다음에 함께 하면 좋은 일은 무엇인가요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"둘레의 글에서 겹받침 낱말을 찾은 다음에 함께 하면 좋은 일은 무엇인가요?","options":[{"t":"찾은 낱말을 소리 내어 읽어요","correct":true},{"t":"책을 덮고 그냥 넘어가요","mis":"K1-2-u2-X15"},{"t":"그림만 그려요","mis":"K1-2-u2-X15"}],"explanation":["소리 내어 읽어야 바르게 읽는 법도 익혀져요.","그냥 넘어가거나 그림만 그리면 배운 것이 남지 않아요.","찾기 → 읽기 → 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#8','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'mc','auto','카드에 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],true,'{"seq":8,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"카드에 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K1-2-u2-X04"},{"t":"달ㄱ","mis":"K1-2-u2-X05"}],"explanation":["꼬꼬댁 우는 새는 「닭」, 받침은 ㄺ이에요.","소리대로 「닥」이라 쓰거나 받침을 떼어 쓰면 안 돼요.","받침 자리에 두 자음자를 함께 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 카드에 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"흑","mis":"K1-2-u2-X04"},{"t":"흘ㄱ","mis":"K1-2-u2-X05"}],"explanation":["땅의 부드러운 것은 「흙」, 받침은 ㄺ이에요.","소리대로 쓰거나 받침을 떼면 안 돼요.","두 자음자를 함께 써요."],"asset":null},{"stem":"이번에는 다른 보기예요. 카드에 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K1-2-u2-X04"},{"t":"갓","mis":"K1-2-u2-X06"}],"explanation":["물건의 돈은 「값」, 받침은 ㅄ이에요.","「갑」은 소리대로, 「갓」은 다른 낱말이에요.","뜻을 떠올리고 받침을 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#9','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',2,'ox','auto','낱말 카드에서 가장 중요한 것은 그림을 예쁘게 그리는 것이에요.',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":9,"concept":"K1-2-u2-C6","difficulty":2,"kind":"ox","stem":"낱말 카드에서 가장 중요한 것은 그림을 예쁘게 그리는 것이에요.","answer":"X","reason_options":[{"t":"낱말을 바르게 쓰는 것이 이 활동의 목적이니까","correct":true},{"t":"그림이 예뻐야 카드가 되니까","mis":"K1-2-u2-X15"}],"mis":"K1-2-u2-X15","explanation":["그림은 거들 뿐이에요.","겹받침을 익히려고 카드를 만드는 거예요.","낱말을 바르게 썼는지부터 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_basic#10','kor',1,2,'u2','L13','g1_2_kor_u2_L13_basic','lesson_basic','K1-2-u2-C6',3,'mc','auto','「낡은 우산」에서 겹받침 낱말을 두 개 찾아 카드를 만들려고 해요. 알맞은 짝은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":10,"concept":"K1-2-u2-C6","difficulty":3,"kind":"mc","stem":"「낡은 우산」에서 겹받침 낱말을 두 개 찾아 카드를 만들려고 해요. 알맞은 짝은 어느 것인가요?","options":[{"t":"낡은 · 넓고","correct":true},{"t":"우산 · 손잡이","mis":"K1-2-u2-X02"},{"t":"포근 · 창고","mis":"K1-2-u2-X02"}],"explanation":["「낡」은 ㄺ, 「넓」은 ㄼ이에요.","「우산」·「손잡이」·「포근」·「창고」에는 겹받침이 없어요.","받침 자리를 하나씩 봐요."],"asset":{"type":"passage","lines":["비 오는 날, 유찬이는 창고에서 우산 하나를 찾았어요.","우산은 아주 낡은 우산이었어요.","손잡이가 닳아 있고 천도 얇았어요.","\"괜찮아. 아직 쓸 수 있어.\"","우산 속은 생각보다 넓고 포근했어요.","집까지 오는 길이 하나도 멀지 않았어요."],"title":"낡은 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#1','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',2,'mc','auto','「여덟 · 구름 · 닭 · 별」에서 겹받침 낱말만 고른 짝은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],true,'{"seq":1,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"「여덟 · 구름 · 닭 · 별」에서 겹받침 낱말만 고른 짝은 어느 것인가요?","options":[{"t":"여덟 · 닭","correct":true},{"t":"구름 · 별","mis":"K1-2-u2-X02"},{"t":"여덟 · 별","mis":"K1-2-u2-X02"}],"explanation":["「덟」은 ㄼ, 「닭」은 ㄺ이에요.","「구름」·「별」은 받침이 하나예요.","받침 자리를 봐요."],"variant_rule":{"alt":[{"stem":"「흙 · 달 · 값 · 나무」에서 겹받침 낱말만 고른 짝은 어느 것인가요?","options":[{"t":"흙 · 값","correct":true},{"t":"달 · 나무","mis":"K1-2-u2-X02"},{"t":"흙 · 달","mis":"K1-2-u2-X02"}],"explanation":["「흙」은 ㄺ, 「값」은 ㅄ이에요.","「달」은 받침 하나, 「나무」는 받침이 없어요.","받침 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#2','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',2,'mc','auto','낱말 카드 묶음을 만드는 차례에서 첫걸음은 무엇인가요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":2,"concept":"K1-2-u2-C6","difficulty":2,"kind":"mc","stem":"낱말 카드 묶음을 만드는 차례에서 첫걸음은 무엇인가요?","options":[{"t":"책이나 둘레에서 겹받침 낱말 찾기","correct":true},{"t":"그림을 예쁘게 그리기","mis":"K1-2-u2-X15"},{"t":"카드를 실로 묶기","mis":"K1-2-u2-X15"}],"explanation":["낱말을 먼저 찾아야 카드를 만들어요.","그림과 묶기는 그다음이에요.","찾기 → 쓰기 → 묶기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#3','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'error','auto','카드에 쓸 겹받침 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#4','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'mc','auto','「씨앗을 심은 날」을 읽고 답하세요. 「굵어졌어요」는 무슨 뜻인가요?',ARRAY['K1-2-u2-X16']::text[],true,'{"seq":4,"concept":"K1-2-u2-C6","difficulty":3,"kind":"mc","stem":"「씨앗을 심은 날」을 읽고 답하세요. 「굵어졌어요」는 무슨 뜻인가요?","options":[{"t":"가늘던 것이 두꺼워졌어요","correct":true},{"t":"구부러졌어요","mis":"K1-2-u2-X16"},{"t":"없어졌어요","mis":"K1-2-u2-X16"}],"explanation":["싹이 자라서 두꺼워졌다는 뜻이에요.","구부러지거나 없어진 것이 아니에요.","낱말이 나온 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["마당에 흙을 담고 씨앗을 심었어요.","물이 맑아 보였어요.","며칠 뒤 싹이 굵어졌어요."],"title":"씨앗을 심은 날"},"variant_rule":{"alt":[{"stem":"「씨앗을 심은 날」을 읽고 답하세요. 「맑아 보였어요」는 무슨 뜻인가요?","options":[{"t":"흐리지 않고 깨끗해 보였어요","correct":true},{"t":"달게 보였어요","mis":"K1-2-u2-X16"},{"t":"무거워 보였어요","mis":"K1-2-u2-X16"}],"explanation":["물이 깨끗하고 환해 보였다는 뜻이에요.","달거나 무거운 것이 아니에요.","앞뒤 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["마당에 흙을 담고 씨앗을 심었어요.","물이 맑아 보였어요.","며칠 뒤 싹이 굵어졌어요."],"title":"씨앗을 심은 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#5','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'ox','auto','「흙」 카드에 「흑」이라고 쓰면 안 돼요.',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":5,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"「흙」 카드에 「흑」이라고 쓰면 안 돼요.","answer":"O","reason_options":[{"t":"소리는 [흑]이라도 쓸 때는 낱말대로 ㄺ을 써야 하니까","correct":true},{"t":"카드에는 아무렇게나 써도 되니까","mis":"K1-2-u2-X04"}],"mis":"K1-2-u2-X04","explanation":["소리와 글자가 달라도 낱말대로 써요.","카드에서 제일 중요한 것이 바르게 쓰기예요.","「값」을 「갑」이라 쓰지 않는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#6','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'match','auto','만든 카드를 소리 내어 읽어요. 낱말과 그 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u2-C6","difficulty":3,"kind":"match","stem":"만든 카드를 소리 내어 읽어요. 낱말과 그 소리를 선으로 이어 보세요.","pairs":[{"l":"값","r":"[갑]"},{"l":"닭","r":"[닥]"},{"l":"여덟","r":"[여덜]"}],"mis":"K1-2-u2-X07","explanation":["낱말이 끝나면 겹받침 소리는 하나만 나요.","쓸 때는 두 자음자를 다 써요.","읽기와 쓰기를 둘 다 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#7','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',3,'mc','auto','낱말 카드 만들기로 익히려는 것은 무엇인가요?',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":3,"kind":"mc","stem":"낱말 카드 만들기로 익히려는 것은 무엇인가요?","options":[{"t":"겹받침 낱말을 바르게 쓰고 읽기","correct":true},{"t":"그림을 잘 그리기","mis":"K1-2-u2-X15"},{"t":"카드를 많이 모으기","mis":"K1-2-u2-X15"}],"explanation":["겹받침 낱말을 바르게 쓰고 읽으려고 카드를 만들어요.","그림이나 카드 수는 목적이 아니에요.","무엇을 배우려는 활동인지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#8','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',4,'sa','auto','카드에 쓸 낱말이에요. 그림이 「꼬꼬댁 우는 새」일 때 낱말을 바르게 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u2-C6","difficulty":4,"kind":"sa","stem":"카드에 쓸 낱말이에요. 그림이 「꼬꼬댁 우는 새」일 때 낱말을 바르게 쓰세요.","answer":["닭"],"explanation":["꼬꼬댁 우는 새는 「닭」이에요.","소리는 [닥]이지만 받침은 ㄺ이에요.","뜻을 떠올리고 겹받침을 써요."],"variant_rule":{"alt":[{"stem":"카드에 쓸 낱말이에요. 그림이 「화분에 담는 땅의 부드러운 것」일 때 낱말을 바르게 쓰세요.","answer":["흙"],"explanation":["땅의 부드러운 것은 「흙」이에요.","소리는 [흑]이지만 받침은 ㄺ이에요.","뜻을 떠올려요."],"asset":null},{"stem":"카드에 쓸 낱말이에요. 그림이 「8이라고 쓴 수」일 때 낱말을 바르게 쓰세요.","answer":["여덟"],"explanation":["8은 「여덟」이에요.","소리는 [여덜]이지만 받침은 ㄼ이에요.","뜻을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#9','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',4,'essay','teacher','우리 교실이나 책에서 겹받침이 있는 낱말을 하나 찾아 쓰고, 그 카드에 어떤 그림을 그릴지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C6","difficulty":4,"kind":"essay","stem":"우리 교실이나 책에서 겹받침이 있는 낱말을 하나 찾아 쓰고, 그 카드에 어떤 그림을 그릴지 쓰세요.","answer_guide":{"answer":"예: 「읽다」 — 책을 보는 아이를 그린다. / 「값」 — 물건과 돈을 그린다. — 겹받침 낱말을 바르게 쓰고 뜻에 맞는 그림이면 맞아요.","scoring_points":["찾은 낱말에 겹받침이 있는가","받침을 바르게 썼는가","그림이 낱말의 뜻과 어울리는가"]},"explanation":["둘레의 글에서 겹받침 낱말을 찾아요.","낱말을 바르게 쓰고 뜻에 맞는 그림을 정해요.","찾은 낱말은 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_L13_challenge#10','kor',1,2,'u2','L13','g1_2_kor_u2_L13_challenge','lesson_challenge','K1-2-u2-C6',4,'essay','teacher','「값」 카드를 만들어요. 그림에 무엇을 그릴지 쓰고, 「갑」이 아니라 「값」이라고 써야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u2-C6","difficulty":4,"kind":"essay","stem":"「값」 카드를 만들어요. 그림에 무엇을 그릴지 쓰고, 「갑」이 아니라 「값」이라고 써야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 물건과 돈을 그린다. 소리는 [갑]이지만 「갑」은 상자라 뜻이 달라지므로 낱말대로 「값」이라고 써야 한다. — 그림과 까닭이 맞으면 돼요.","scoring_points":["그림이 「값」의 뜻과 어울리는가","소리대로가 아니라 낱말대로 쓴다는 까닭을 말했는가","받침 ㅄ을 바르게 썼는가"]},"explanation":["물건의 돈이 「값」이에요.","소리대로 쓰면 뜻이 달라져요.","뜻을 먼저 떠올리고 받침을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#1','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',1,'mc','auto','「낚」의 받침 ㄲ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「낚」의 받침 ㄲ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["같은 자음자 ㄱ이 겹쳤으니 쌍받침이에요.","겹받침은 다른 자음자 둘이에요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"낚","text":"받침 ㄲ"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#2','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',1,'mc','auto','다음 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"넓다","correct":true},{"t":"산","mis":"K1-2-u2-X02"},{"t":"나무","mis":"K1-2-u2-X02"}],"explanation":["「넓」의 받침은 ㄹ과 ㅂ이에요.","「산」은 받침 하나, 「나무」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#3','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',1,'mc','auto','물건을 살 때 내는 돈을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"물건을 살 때 내는 돈을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K1-2-u2-X04"},{"t":"갓","mis":"K1-2-u2-X06"}],"explanation":["돈을 뜻하는 낱말은 「값」이에요.","「갑」은 소리대로 쓴 것, 「갓」은 다른 낱말이에요.","뜻을 떠올리고 받침을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#4','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',1,'mc','auto','「읽다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X07','K1-2-u2-X08']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「읽다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[익따]","correct":true},{"t":"[일ㄱ따]","mis":"K1-2-u2-X07"},{"t":"[이따]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 자음이 오니 하나만 소리 나요.","둘 다 내거나 받침을 빼면 안 돼요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#5','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',1,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?","options":[{"t":"1학년 하은","correct":true},{"t":"도서관 선생님","mis":"K1-2-u2-X12"},{"t":"늦게 돌려준 친구","mis":"K1-2-u2-X12"}],"explanation":["첫 줄에 글쓴이가 적혀 있어요.","선생님과 친구는 글에 나오는 사람이에요.","글의 처음을 봐요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#6','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',1,'mc','auto','「기다려지는 때」를 읽고 답하세요. 체육 선생님이 기다리는 때는 언제인가요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「기다려지는 때」를 읽고 답하세요. 체육 선생님이 기다리는 때는 언제인가요?","options":[{"t":"운동장에 해가 드는 때","correct":true},{"t":"국이 끓는 때","mis":"K1-2-u2-X13"},{"t":"책을 읽는 때","mis":"K1-2-u2-X13"}],"explanation":["넷째 줄에 체육 선생님의 말이 있어요.","국은 조리사, 책은 도서관 선생님이에요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#7','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C6',1,'mc','auto','겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"구름","mis":"K1-2-u2-X02"},{"t":"바다","mis":"K1-2-u2-X02"}],"explanation":["「값」에는 겹받침 ㅄ이 있어요.","「구름」은 받침 하나, 「바다」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#8','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',1,'mc','auto','「바퀴」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「바퀴」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[바퀴]","correct":true},{"t":"[바키]","mis":"K1-2-u2-X09"},{"t":"[바꾸]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ는 입술을 동그랗게 모아 소리 내요.","ㅣ나 ㅜ로 바꾸어 읽지 않아요.","거울을 보며 입 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#9','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',2,'match','auto','낱말과 그 낱말의 받침을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"값","r":"ㅄ"},{"l":"읽다","r":"ㄺ"},{"l":"여덟","r":"ㄼ"}],"mis":"K1-2-u2-X05","explanation":["「값」은 ㅄ, 「읽」은 ㄺ이에요.","「덟」은 ㄼ이에요.","끝소리 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
