INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#11','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',2,'mc','auto','「읽어」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":11,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「읽어」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[일거]","correct":true},{"t":"[이거]","mis":"K1-2-u2-X08"},{"t":"[익어]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 오니 둘 다 소리 나요.","「읽다[익따]」와 달라요.","뒤에 오는 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#12','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',2,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":12,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"빌린 책은 제날짜에 돌려주자","correct":true},{"t":"책을 많이 빌리자","mis":"K1-2-u2-X11"},{"t":"하은이는 날짜를 적어 둔다","mis":"K1-2-u2-X11"}],"explanation":["제목과 마지막 줄이 같은 말이에요.","「날짜를 적어 둔다」는 하은이가 한 일이에요.","제목과 까닭을 이어요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#13','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',2,'match','auto','「기다려지는 때」에서 인물과 그 인물이 말한 때를 선으로 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"「기다려지는 때」에서 인물과 그 인물이 말한 때를 선으로 이어 보세요.","pairs":[{"l":"조리사 선생님","r":"국이 끓는 때"},{"l":"도서관 선생님","r":"책을 읽는 때"},{"l":"체육 선생님","r":"해가 드는 때"}],"mis":"K1-2-u2-X13","explanation":["조리사 선생님은 국, 도서관 선생님은 책이에요.","체육 선생님은 해가 드는 때예요.","인물마다 한 말을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#14','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C6',2,'mc','auto','다음 글에서 겹받침이 있는 낱말은 모두 몇 개인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#15','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',2,'ox','auto','「없다」와 「업다」는 소리가 같으니 아무거나 써도 돼요.',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":15,"concept":"K1-2-u2-C2","difficulty":2,"kind":"ox","stem":"「없다」와 「업다」는 소리가 같으니 아무거나 써도 돼요.","answer":"X","reason_options":[{"t":"소리가 같아도 뜻이 다른 낱말이니까","correct":true},{"t":"받침만 다르면 같은 낱말이니까","mis":"K1-2-u2-X06"}],"mis":"K1-2-u2-X06","explanation":["「없다」는 있지 않다, 「업다」는 등에 업다예요.","뜻이 다르면 다른 낱말이에요.","뜻을 그림으로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#16','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',2,'mc','auto','「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":16,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?","options":[{"t":"늦게 돌려주면 기다리는 친구가 오래 기다려서","correct":true},{"t":"도서관이 넓다는 것을 알리려고","mis":"K1-2-u2-X11"},{"t":"책을 많이 빌리라고","mis":"K1-2-u2-X11"}],"explanation":["넷째·다섯째 줄에 까닭이 있어요.","도서관 크기나 빌리는 양과는 상관없어요.","「그런데」 뒤를 읽어요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#17','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C1',3,'error','auto','겹받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#18','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',3,'error','auto','「신발이 너무 짤바요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「신발이 너무 짤바요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「짤바요」 — 소리대로 썼어요. 「짧아요」예요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「신발」 — 「신바」로 써야 해요","mis":"K1-2-u2-X05"},{"t":"「너무」 — 받침을 넣어야 해요","mis":"K1-2-u2-X05"}],"explanation":["[짤바요]로 들려도 「짧아요」라고 써요.","「신발」과 「너무」는 바르게 썼어요.","낱말대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#19','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C3',3,'ox','auto','겹받침 뒤에 모음이 오면 두 자음이 다 소리 나요.',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"ox","stem":"겹받침 뒤에 모음이 오면 두 자음이 다 소리 나요.","answer":"O","reason_options":[{"t":"「읽어[일거]」처럼 받침 하나가 뒤 글자로 넘어가니까","correct":true},{"t":"겹받침은 언제나 하나만 소리 나니까","mis":"K1-2-u2-X08"}],"mis":"K1-2-u2-X08","explanation":["모음 앞에서는 둘 다 소리 나요.","「읽다[익따]」와 「읽어[일거]」를 견주어요.","뒤에 오는 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#20','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',3,'mc','auto','「기다려지는 때」에서 세 사람의 답이 서로 다른 까닭은 무엇일까요?',ARRAY['K1-2-u2-X14','K1-2-u2-X13']::text[],false,'{"seq":20,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"「기다려지는 때」에서 세 사람의 답이 서로 다른 까닭은 무엇일까요?","options":[{"t":"사람마다 하는 일과 겪은 일이 달라서","correct":true},{"t":"한 사람만 바르게 답해서","mis":"K1-2-u2-X14"},{"t":"연서가 물음을 잘못 물어서","mis":"K1-2-u2-X13"}],"explanation":["하는 일이 다르니 기다리는 때도 달라요.","누가 맞고 틀린 것이 아니에요.","물음은 하나여도 답은 여럿이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#21','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',3,'error','auto','하고 싶은 말을 찾는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#22','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C6',3,'ox','auto','낱말 카드를 만들 때 가장 마음 쓸 것은 그림을 오래 예쁘게 꾸미는 것이에요.',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":22,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"낱말 카드를 만들 때 가장 마음 쓸 것은 그림을 오래 예쁘게 꾸미는 것이에요.","answer":"X","reason_options":[{"t":"낱말을 바르게 쓰는 것이 이 활동의 목적이니까","correct":true},{"t":"그림이 예뻐야 카드가 되니까","mis":"K1-2-u2-X15"}],"mis":"K1-2-u2-X15","explanation":["그림은 거들 뿐이에요.","겹받침을 익히려고 카드를 만드는 거예요.","낱말을 바르게 썼는지부터 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#23','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C2',4,'sa','auto','[갑]이라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (물건을 살 때 내는 돈)','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"[갑]이라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (물건을 살 때 내는 돈)","answer":["값"],"explanation":["돈을 뜻하는 낱말은 「값」이에요.","소리는 [갑]이지만 받침은 ㅄ이에요.","뜻을 떠올리고 겹받침을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#24','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C5',4,'essay','teacher','「기다려지는 때」를 읽고, 조리사 선생님의 말에서 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「기다려지는 때」를 읽고, 조리사 선생님의 말에서 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 조리사 선생님은 국을 맛있게 끓이는 일을 소중하게 여긴다. — 국이 끓는 때를 기다린다는 말과 이어서 짐작하면 맞아요.","scoring_points":["조리사 선생님의 말을 근거로 썼는가","하는 일과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["조리사 선생님은 국이 끓는 때를 기다린다고 말했어요.","그 말에서 하는 일을 소중히 여긴다는 생각이 보여요.","말과 행동에서 짐작해요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_a#25','kor',1,2,'u2','','g1_2_kor_u2_review_a','unit_review','K1-2-u2-C4',4,'essay','teacher','「빌린 책은 제날짜에 돌려주자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「빌린 책은 제날짜에 돌려주자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 기다리는 친구가 오래 기다리지 않게 빌린 책은 제날짜에 돌려주자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「제날짜에 돌려주자」는 말이 있는가","까닭(기다리는 친구)을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","넷째·다섯째 줄이 까닭이에요.","둘을 「~니까 ~하자」로 이어요."],"asset":{"type":"passage","lines":["1학년 하은","나는 도서관에서 책을 빌리면 돌려줄 날짜를 적어 둡니다.","그러면 잊지 않고 제날짜에 돌려줄 수 있습니다.","그런데 며칠씩 늦게 돌려주는 친구들이 있습니다.","그러면 그 책을 기다리는 친구가 오래 기다려야 합니다.","빌린 책은 제날짜에 돌려줍시다. 그래야 여러 친구가 함께 읽을 수 있습니다."],"title":"빌린 책은 제날짜에 돌려주자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#1','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C1',1,'mc','auto','「값」의 받침 ㅄ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「값」의 받침 ㅄ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"첫소리","mis":"K1-2-u2-X03"}],"explanation":["ㅂ과 ㅅ, 다른 자음자 둘이라 겹받침이에요.","쌍받침은 같은 자음자가 겹친 거예요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"값","text":"받침 ㅄ"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#2','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C1',1,'mc','auto','다음 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"책","mis":"K1-2-u2-X02"},{"t":"오리","mis":"K1-2-u2-X02"}],"explanation":["「값」의 받침은 ㅂ과 ㅅ이에요.","「책」은 받침 하나, 「오리」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#3','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',1,'mc','auto','「있지 않다」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"「있지 않다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"없다","correct":true},{"t":"업다","mis":"K1-2-u2-X04"},{"t":"얻다","mis":"K1-2-u2-X06"}],"explanation":["있지 않은 것은 「없다」예요.","「업다」는 등에 업다, 「얻다」는 받다예요.","뜻을 떠올리고 받침을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#4','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',1,'mc','auto','「값」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X07','K1-2-u2-X08']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「값」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[갑]","correct":true},{"t":"[갑스]","mis":"K1-2-u2-X07"},{"t":"[가]","mis":"K1-2-u2-X08"}],"explanation":["낱말이 끝나니 하나만 소리 나요.","둘 다 내거나 받침을 빼면 안 돼요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#5','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',1,'mc','auto','「학용품에 이름을 쓰자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?","options":[{"t":"1학년 도윤","correct":true},{"t":"연필 주인","mis":"K1-2-u2-X12"},{"t":"선생님","mis":"K1-2-u2-X12"}],"explanation":["첫 줄에 글쓴이가 적혀 있어요.","연필 주인이나 선생님이 아니에요.","글의 처음을 봐요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#6','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',1,'mc','auto','「제일 기다리는 날」을 읽고 답하세요. 동생이 기다리는 날은 언제인가요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「제일 기다리는 날」을 읽고 답하세요. 동생이 기다리는 날은 언제인가요?","options":[{"t":"생일","correct":true},{"t":"씨앗을 심는 날","mis":"K1-2-u2-X13"},{"t":"일요일","mis":"K1-2-u2-X13"}],"explanation":["넷째 줄에 동생의 말이 있어요.","씨앗은 할머니, 일요일은 아빠예요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#7','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C6',1,'mc','auto','겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"달","mis":"K1-2-u2-X02"},{"t":"별","mis":"K1-2-u2-X02"}],"explanation":["「흙」에는 겹받침 ㄺ이 있어요.","「달」·「별」은 받침이 하나예요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#8','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',1,'mc','auto','「튀김」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「튀김」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[튀김]","correct":true},{"t":"[티김]","mis":"K1-2-u2-X09"},{"t":"[투김]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ는 입술을 동그랗게 모아 소리 내요.","ㅣ나 ㅜ로 바꾸어 읽지 않아요.","입 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#9','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C1',2,'match','auto','낱말과 그 낱말의 받침을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"없다","r":"ㅄ"},{"l":"닭","r":"ㄺ"},{"l":"넓다","r":"ㄼ"}],"mis":"K1-2-u2-X05","explanation":["「없」은 ㅄ, 「닭」은 ㄺ이에요.","「넓」은 ㄼ이에요.","끝소리 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
