INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#11','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',2,'mc','auto','「낡은」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":11,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「낡은」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[날근]","correct":true},{"t":"[나근]","mis":"K1-2-u2-X08"},{"t":"[낙은]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 오니 둘 다 소리 나요.","받침 하나를 빼면 안 돼요.","뒤에 오는 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#12','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',2,'mc','auto','「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":12,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"학용품에 이름을 쓰자","correct":true},{"t":"연필을 많이 사자","mis":"K1-2-u2-X11"},{"t":"연필이 상자에 쌓인다","mis":"K1-2-u2-X11"}],"explanation":["제목과 마지막 줄이 같은 말이에요.","「상자에 쌓인다」는 있었던 일이에요.","제목과 까닭을 이어요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#13','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',2,'match','auto','「제일 기다리는 날」에서 인물과 그 인물이 말한 날을 선으로 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"「제일 기다리는 날」에서 인물과 그 인물이 말한 날을 선으로 이어 보세요.","pairs":[{"l":"할머니","r":"씨앗을 심는 날"},{"l":"아빠","r":"함께 밥을 먹는 일요일"},{"l":"동생","r":"생일"}],"mis":"K1-2-u2-X13","explanation":["할머니는 텃밭, 아빠는 함께 먹는 밥이에요.","동생은 생일이에요.","인물마다 한 말을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
