INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#15','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',2,'ox','auto','「값」과 「갑」은 소리가 같으니 아무거나 써도 돼요.',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":15,"concept":"K1-2-u2-C2","difficulty":2,"kind":"ox","stem":"「값」과 「갑」은 소리가 같으니 아무거나 써도 돼요.","answer":"X","reason_options":[{"t":"소리가 같아도 뜻이 다른 낱말이니까","correct":true},{"t":"받침만 다르면 같은 낱말이니까","mis":"K1-2-u2-X06"}],"mis":"K1-2-u2-X06","explanation":["「값」은 돈, 「갑」은 상자예요.","뜻이 다르면 다른 낱말이에요.","뜻을 그림으로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#16','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',2,'mc','auto','「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":16,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「학용품에 이름을 쓰자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?","options":[{"t":"이름이 없어 주인을 못 찾는 연필이 쌓여서","correct":true},{"t":"연필이 너무 짧아서","mis":"K1-2-u2-X11"},{"t":"연필을 많이 사라고","mis":"K1-2-u2-X11"}],"explanation":["둘째~넷째 줄에 까닭이 있어요.","연필 길이나 사는 것과는 상관없어요.","글쓴이가 본 일을 찾아요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#17','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C1',3,'error','auto','겹받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#18','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',3,'error','auto','「연필 갑이 얼마예요?」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「연필 갑이 얼마예요?」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「갑」 — 소리대로 썼어요. 돈을 뜻하는 「값」이에요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「연필」 — 「연피」로 써야 해요","mis":"K1-2-u2-X05"},{"t":"「얼마」 — 받침을 넣어야 해요","mis":"K1-2-u2-X05"}],"explanation":["돈을 뜻하면 「값」이라고 써요.","「연필」과 「얼마」는 바르게 썼어요.","뜻을 떠올리고 받침을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#19','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C3',3,'ox','auto','겹받침이 있는 낱말이 끝나면 소리는 하나만 나요.',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"ox","stem":"겹받침이 있는 낱말이 끝나면 소리는 하나만 나요.","answer":"O","reason_options":[{"t":"「값[갑]」·「닭[닥]」처럼 하나만 들리니까","correct":true},{"t":"받침이 둘이면 언제나 둘 다 소리 나니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["낱말 끝에서는 하나만 소리 나요.","둘 다 내면 [갑스]처럼 틀려요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#20','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',3,'mc','auto','나와 답이 다른 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":20,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"나와 답이 다른 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 생각했는지 들려줄래?","correct":true},{"t":"네 답은 틀렸어.","mis":"K1-2-u2-X14"},{"t":"내 답으로 바꿔.","mis":"K1-2-u2-X14"}],"explanation":["까닭을 물어보면 생각이 더 넓어져요.","다르다고 틀린 것이 아니에요.","다른 답에도 그 사람의 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#21','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',3,'error','auto','하고 싶은 말을 찾는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#22','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C6',3,'ox','auto','「흙」 카드에 「흑」이라고 쓰면 안 돼요.',ARRAY['K1-2-u2-X04']::text[],false,'{"seq":22,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"「흙」 카드에 「흑」이라고 쓰면 안 돼요.","answer":"O","reason_options":[{"t":"소리는 [흑]이라도 쓸 때는 낱말대로 ㄺ을 써야 하니까","correct":true},{"t":"카드에는 아무렇게나 써도 되니까","mis":"K1-2-u2-X04"}],"mis":"K1-2-u2-X04","explanation":["소리와 글자가 달라도 낱말대로 써요.","카드에서 제일 중요한 것이 바르게 쓰기예요.","「값」을 「갑」이라 쓰지 않는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#23','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C2',4,'sa','auto','[업따]라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (있지 않다)','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"[업따]라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (있지 않다)","answer":["없다"],"explanation":["있지 않은 것은 「없다」예요.","소리는 [업따]지만 받침은 ㅄ이에요.","뜻을 떠올리고 겹받침을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#24','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C5',4,'essay','teacher','「제일 기다리는 날」을 읽고, 아빠의 말에서 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「제일 기다리는 날」을 읽고, 아빠의 말에서 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 아빠는 온 식구가 함께하는 것을 소중하게 여긴다. — 함께 밥을 먹는 일요일을 기다린다는 말과 이어서 짐작하면 맞아요.","scoring_points":["아빠의 말을 근거로 썼는가","함께하는 것과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["아빠는 함께 밥을 먹는 일요일을 기다린다고 말했어요.","그 말에서 식구가 함께하는 것을 소중히 여기는 생각이 보여요.","말과 행동에서 짐작해요."],"asset":{"type":"passage","lines":["지호는 집에서 식구들에게 같은 것을 물었어요. \"제일 기다리는 날은 언제예요?\"","할머니가 말했어요. \"텃밭에 씨앗을 심는 날이지.\"","아빠가 말했어요. \"온 식구가 함께 밥을 먹는 일요일이란다.\"","동생이 말했어요. \"내 생일! 케이크 먹는 날이야.\"","지호는 생각했어요. ''같은 물음인데 답이 다 다르네.''"],"title":"제일 기다리는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_b#25','kor',1,2,'u2','','g1_2_kor_u2_review_b','unit_review','K1-2-u2-C4',4,'essay','teacher','「학용품에 이름을 쓰자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「학용품에 이름을 쓰자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 잃어도 다시 찾을 수 있게 학용품에 이름을 쓰자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「이름을 쓰자」는 말이 있는가","까닭(주인을 못 찾는다)을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","둘째~넷째 줄이 까닭이에요.","둘을 「~니까 ~하자」로 이어요."],"asset":{"type":"passage","lines":["1학년 도윤","우리 반에는 주인을 잃은 연필이 많습니다.","이름이 없어서 누구 것인지 알 수 없습니다.","잃어버린 연필은 그대로 상자에 쌓입니다.","학용품에 이름을 씁시다. 그러면 잃어도 다시 찾을 수 있습니다."],"title":"학용품에 이름을 쓰자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#1','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C1',1,'mc','auto','「있」의 받침 ㅆ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「있」의 받침 ㅆ은 무엇인가요?","options":[{"t":"쌍받침","correct":true},{"t":"겹받침","mis":"K1-2-u2-X01"},{"t":"끝소리가 아니에요","mis":"K1-2-u2-X03"}],"explanation":["같은 자음자 ㅅ이 겹쳤으니 쌍받침이에요.","겹받침은 다른 자음자 둘이에요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"있","text":"받침 ㅆ"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#2','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C1',1,'mc','auto','다음 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"강","mis":"K1-2-u2-X02"},{"t":"소","mis":"K1-2-u2-X02"}],"explanation":["「읽」의 받침은 ㄹ과 ㄱ이에요.","「강」은 받침 하나, 「소」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#3','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',1,'mc','auto','「책을 보다」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"「책을 보다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"익다","mis":"K1-2-u2-X04"},{"t":"일다","mis":"K1-2-u2-X06"}],"explanation":["책을 보는 것은 「읽다」예요.","「익다」는 소리대로 쓴 것, 「일다」는 다른 낱말이에요.","뜻을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#4','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',1,'mc','auto','「닭」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X07','K1-2-u2-X08']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「닭」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[닥]","correct":true},{"t":"[달ㄱ]","mis":"K1-2-u2-X07"},{"t":"[다]","mis":"K1-2-u2-X08"}],"explanation":["낱말이 끝나니 하나만 소리 나요.","둘 다 내거나 받침을 빼면 안 돼요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#5','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',1,'mc','auto','「공은 바구니에 넣자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「공은 바구니에 넣자」를 읽고 답하세요. 이 글을 쓴 사람은 누구인가요?","options":[{"t":"1학년 서준","correct":true},{"t":"체육 선생님","mis":"K1-2-u2-X12"},{"t":"다음 반 친구","mis":"K1-2-u2-X12"}],"explanation":["첫 줄에 글쓴이가 적혀 있어요.","선생님이나 다음 반은 글쓴이가 아니에요.","글의 처음을 봐요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#6','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',1,'mc','auto','「제일 좋아하는 소리」를 읽고 답하세요. 경비 아저씨가 좋아하는 소리는 무엇인가요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「제일 좋아하는 소리」를 읽고 답하세요. 경비 아저씨가 좋아하는 소리는 무엇인가요?","options":[{"t":"아침에 인사하는 소리","correct":true},{"t":"피아노 소리","mis":"K1-2-u2-X13"},{"t":"맛있다고 말하는 소리","mis":"K1-2-u2-X13"}],"explanation":["넷째 줄에 경비 아저씨의 말이 있어요.","피아노는 음악 선생님, 맛있다는 말은 급식 선생님이에요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["연우는 학교에서 어른들에게 물었어요. \"제일 좋아하는 소리는 뭐예요?\"","음악 선생님이 말했어요. \"피아노 소리지.\"","급식 선생님이 말했어요. \"맛있다고 말하는 소리예요.\"","경비 아저씨가 말했어요. \"아침에 인사하는 소리란다.\"","연우는 생각했어요. ''다 자기가 하는 일과 이어진 소리네.''"],"title":"제일 좋아하는 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#7','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C6',1,'mc','auto','겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"개","mis":"K1-2-u2-X02"},{"t":"소","mis":"K1-2-u2-X02"}],"explanation":["「닭」에는 겹받침 ㄺ이 있어요.","「개」·「소」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#8','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',1,'mc','auto','「쥐」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「쥐」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[쥐]","correct":true},{"t":"[지]","mis":"K1-2-u2-X09"},{"t":"[주]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ는 입술을 동그랗게 모아 소리 내요.","ㅣ나 ㅜ로 바꾸어 읽지 않아요.","입 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#9','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C1',2,'match','auto','낱말과 그 낱말의 받침을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"앉다","r":"ㄵ"},{"l":"흙","r":"ㄺ"},{"l":"짧다","r":"ㄼ"}],"mis":"K1-2-u2-X05","explanation":["「앉」은 ㄵ, 「흙」은 ㄺ이에요.","「짧」은 ㄼ이에요.","끝소리 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
