INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#11','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',2,'mc','auto','「앉아」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":11,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「앉아」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[안자]","correct":true},{"t":"[아자]","mis":"K1-2-u2-X08"},{"t":"[안아]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 오니 둘 다 소리 나요.","「앉다[안따]」와 달라요.","뒤에 오는 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#12','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',2,'mc','auto','「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":12,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"공은 쓰고 나서 바구니에 넣자","correct":true},{"t":"체육 시간을 늘리자","mis":"K1-2-u2-X11"},{"t":"공을 찾느라 시간이 간다","mis":"K1-2-u2-X11"}],"explanation":["제목과 넷째 줄이 같은 말이에요.","「시간이 간다」는 쓴 까닭이에요.","제목과 까닭을 이어요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#13','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',2,'match','auto','「제일 좋아하는 소리」에서 인물과 그 인물이 좋아하는 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"「제일 좋아하는 소리」에서 인물과 그 인물이 좋아하는 소리를 선으로 이어 보세요.","pairs":[{"l":"음악 선생님","r":"피아노 소리"},{"l":"급식 선생님","r":"맛있다고 말하는 소리"},{"l":"경비 아저씨","r":"인사하는 소리"}],"mis":"K1-2-u2-X13","explanation":["음악 선생님은 피아노, 급식 선생님은 맛있다는 말이에요.","경비 아저씨는 인사 소리예요.","인물마다 한 말을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
