INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#15','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',2,'ox','auto','「앉다」와 「안다」는 소리가 같으니 아무거나 써도 돼요.',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":15,"concept":"K1-2-u2-C2","difficulty":2,"kind":"ox","stem":"「앉다」와 「안다」는 소리가 같으니 아무거나 써도 돼요.","answer":"X","reason_options":[{"t":"소리가 같아도 뜻이 다른 낱말이니까","correct":true},{"t":"받침만 다르면 같은 낱말이니까","mis":"K1-2-u2-X06"}],"mis":"K1-2-u2-X06","explanation":["「앉다」는 의자에 앉다, 「안다」는 품에 안다예요.","뜻이 다르면 다른 낱말이에요.","뜻을 몸으로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#16','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',2,'mc','auto','「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":16,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「공은 바구니에 넣자」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?","options":[{"t":"다음 반이 공을 찾느라 시간이 가서","correct":true},{"t":"공이 비싸서","mis":"K1-2-u2-X11"},{"t":"운동장이 넓어서","mis":"K1-2-u2-X11"}],"explanation":["셋째 줄에 까닭이 있어요.","공의 값이나 운동장 크기와는 상관없어요.","글쓴이가 본 일을 찾아요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#17','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C1',3,'error','auto','겹받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#18','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',3,'error','auto','「책상 위에 책이 업서요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「책상 위에 책이 업서요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「업서요」 — 소리대로 썼어요. 「없어요」예요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「책상」 — 「챙상」으로 써야 해요","mis":"K1-2-u2-X05"},{"t":"「위에」 — 받침을 넣어야 해요","mis":"K1-2-u2-X05"}],"explanation":["[업써요]로 들려도 「없어요」라고 써요.","「책상」과 「위에」는 바르게 썼어요.","낱말대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#19','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C3',3,'ox','auto','받침에 자음자가 두 개 있으면 소리도 언제나 두 개가 나요.',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"ox","stem":"받침에 자음자가 두 개 있으면 소리도 언제나 두 개가 나요.","answer":"X","reason_options":[{"t":"뒤에 자음이 오거나 낱말이 끝나면 하나만 소리 나니까","correct":true},{"t":"받침 자음자 수와 소리 수는 언제나 같으니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["「읽다[익따]」·「값[갑]」은 하나만 나요.","모음이 올 때만 둘 다 나요.","소리 내어 읽고 귀로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#20','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',3,'mc','auto','「제일 기다리는 날」에서 식구들의 답이 다 다른 것을 보고 지호는 어떻게 생각해야 할까요?',ARRAY['K1-2-u2-X14']::text[],false,'{"seq":20,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"「제일 기다리는 날」에서 식구들의 답이 다 다른 것을 보고 지호는 어떻게 생각해야 할까요?","options":[{"t":"같은 물음이라도 사람마다 답이 다를 수 있다","correct":true},{"t":"어른의 답만 맞는 답이다","mis":"K1-2-u2-X14"},{"t":"동생의 답은 틀린 답이다","mis":"K1-2-u2-X14"}],"explanation":["사람마다 겪은 일이 달라 답이 달라요.","누구 답이 맞고 틀린 것이 아니에요.","다섯째 줄 지호의 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#21','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',3,'error','auto','하고 싶은 말을 찾는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#22','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C6',3,'ox','auto','겹받침이 있는 낱말은 교과서에만 있어요.',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":22,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"겹받침이 있는 낱말은 교과서에만 있어요.","answer":"X","reason_options":[{"t":"책·알림판·초대장 같은 둘레의 글에도 가득하니까","correct":true},{"t":"우리가 쓰는 말에는 겹받침이 없으니까","mis":"K1-2-u2-X02"}],"mis":"K1-2-u2-X02","explanation":["알림판의 「읽은」, 이야기의 「낡은」처럼 둘레에 많아요.","우리가 쓰는 말에도 「값」·「없다」가 가득해요.","둘레의 글을 둘러봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#23','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C2',4,'sa','auto','[익따]라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (책을 보다)','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"[익따]라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (책을 보다)","answer":["읽다"],"explanation":["책을 보는 것은 「읽다」예요.","소리는 [익따]지만 받침은 ㄺ이에요.","뜻을 떠올리고 겹받침을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#24','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C5',4,'essay','teacher','「제일 좋아하는 소리」를 읽고, 급식 선생님의 말에서 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「제일 좋아하는 소리」를 읽고, 급식 선생님의 말에서 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 급식 선생님은 아이들이 밥을 맛있게 먹는 것을 기쁘게 여긴다. — 맛있다고 말하는 소리를 좋아한다는 말과 이어서 짐작하면 맞아요.","scoring_points":["급식 선생님의 말을 근거로 썼는가","맛있게 먹는 것과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["급식 선생님은 맛있다는 말을 제일 좋아한다고 했어요.","그 말에서 아이들이 잘 먹는 것을 기쁘게 여기는 생각이 보여요.","말과 행동에서 짐작해요."],"asset":{"type":"passage","lines":["연우는 학교에서 어른들에게 물었어요. \"제일 좋아하는 소리는 뭐예요?\"","음악 선생님이 말했어요. \"피아노 소리지.\"","급식 선생님이 말했어요. \"맛있다고 말하는 소리예요.\"","경비 아저씨가 말했어요. \"아침에 인사하는 소리란다.\"","연우는 생각했어요. ''다 자기가 하는 일과 이어진 소리네.''"],"title":"제일 좋아하는 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_c#25','kor',1,2,'u2','','g1_2_kor_u2_review_c','unit_review','K1-2-u2-C4',4,'essay','teacher','「공은 바구니에 넣자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「공은 바구니에 넣자」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 다음 반이 바로 쓸 수 있게 공은 쓰고 나서 바구니에 넣자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「바구니에 넣자」는 말이 있는가","까닭(다음 반이 쓴다)을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","셋째·다섯째 줄이 까닭이에요.","둘을 「~니까 ~하자」로 이어요."],"asset":{"type":"passage","lines":["1학년 서준","체육 시간이 끝나면 공이 운동장에 그대로 남을 때가 있습니다.","다음 반이 쓰려고 하면 공을 찾느라 시간이 갑니다.","공은 쓰고 나서 바구니에 넣읍시다.","그래야 다음 반이 바로 쓸 수 있습니다."],"title":"공은 바구니에 넣자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#1','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',1,'mc','auto','「닭」의 받침 ㄺ은 무엇인가요?',ARRAY['K1-2-u2-X01','K1-2-u2-X03']::text[],false,'{"seq":1,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"「닭」의 받침 ㄺ은 무엇인가요?","options":[{"t":"겹받침","correct":true},{"t":"쌍받침","mis":"K1-2-u2-X01"},{"t":"가운뎃소리","mis":"K1-2-u2-X03"}],"explanation":["ㄹ과 ㄱ, 다른 자음자 둘이라 겹받침이에요.","쌍받침은 같은 자음자가 겹친 거예요.","받침만 떼어 봐요."],"asset":{"type":"scene","icon":"닭","text":"받침 ㄺ"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#2','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',1,'mc','auto','다음 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":2,"concept":"K1-2-u2-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"일곱","mis":"K1-2-u2-X02"},{"t":"개","mis":"K1-2-u2-X02"}],"explanation":["「덟」의 받침은 ㄹ과 ㅂ이에요.","「곱」은 받침 하나, 「개」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#3','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',1,'mc','auto','「좁지 않다」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X06']::text[],false,'{"seq":3,"concept":"K1-2-u2-C2","difficulty":1,"kind":"mc","stem":"「좁지 않다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"넓다","correct":true},{"t":"널다","mis":"K1-2-u2-X04"},{"t":"넙다","mis":"K1-2-u2-X06"}],"explanation":["좁지 않은 것은 「넓다」예요.","「널다」는 빨래를 널다, 「넙다」는 없는 낱말이에요.","뜻을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#4','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',1,'mc','auto','「여덟」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X07','K1-2-u2-X08']::text[],false,'{"seq":4,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「여덟」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[여덜]","correct":true},{"t":"[여덜브]","mis":"K1-2-u2-X07"},{"t":"[여더]","mis":"K1-2-u2-X08"}],"explanation":["낱말이 끝나니 하나만 소리 나요.","둘 다 내거나 받침을 빼면 안 돼요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#5','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',1,'mc','auto','「도서관 앞으로 오세요」를 읽고 답하세요. 이 초대장을 쓴 사람은 누구인가요?',ARRAY['K1-2-u2-X12']::text[],false,'{"seq":5,"concept":"K1-2-u2-C4","difficulty":1,"kind":"mc","stem":"「도서관 앞으로 오세요」를 읽고 답하세요. 이 초대장을 쓴 사람은 누구인가요?","options":[{"t":"1학년 3반","correct":true},{"t":"1학년 친구들","mis":"K1-2-u2-X12"},{"t":"도서관 선생님","mis":"K1-2-u2-X12"}],"explanation":["글 끝에 「1학년 3반 올림」이라고 글쓴이가 적혀 있어요.","「1학년 친구들」은 받는 사람이에요.","글의 끝을 봐요."],"asset":{"type":"passage","lines":["1학년 친구들에게","다음 주 화요일에 우리 반이 만든 낱말 카드를 도서관 앞에 붙입니다.","쉬는 시간에 와서 보고 마음에 드는 낱말을 골라 보세요.","1학년 3반 올림"],"title":"도서관 앞으로 오세요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#6','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',1,'mc','auto','「기다려지는 때」를 읽고 답하세요. 도서관 선생님이 기다리는 때는 언제인가요?',ARRAY['K1-2-u2-X13']::text[],false,'{"seq":6,"concept":"K1-2-u2-C5","difficulty":1,"kind":"mc","stem":"「기다려지는 때」를 읽고 답하세요. 도서관 선생님이 기다리는 때는 언제인가요?","options":[{"t":"아이들이 책을 읽는 때","correct":true},{"t":"국이 끓는 때","mis":"K1-2-u2-X13"},{"t":"해가 드는 때","mis":"K1-2-u2-X13"}],"explanation":["셋째 줄에 도서관 선생님의 말이 있어요.","국은 조리사, 해는 체육 선생님이에요.","누가 한 말인지 짚어요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#7','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C6',1,'mc','auto','겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u2-X02']::text[],false,'{"seq":7,"concept":"K1-2-u2-C6","difficulty":1,"kind":"mc","stem":"겹받침 낱말 카드에 쓸 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"보다","mis":"K1-2-u2-X02"},{"t":"가다","mis":"K1-2-u2-X02"}],"explanation":["「읽」에는 겹받침 ㄺ이 있어요.","「보다」·「가다」는 받침이 없어요.","받침 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#8','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',1,'mc','auto','「귀」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X09']::text[],false,'{"seq":8,"concept":"K1-2-u2-C3","difficulty":1,"kind":"mc","stem":"「귀」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[귀]","correct":true},{"t":"[기]","mis":"K1-2-u2-X09"},{"t":"[구]","mis":"K1-2-u2-X09"}],"explanation":["ㅟ는 입술을 동그랗게 모아 소리 내요.","ㅣ나 ㅜ로 바꾸어 읽지 않아요.","입 모양을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#9','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',2,'match','auto','낱말과 그 낱말의 받침을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 낱말의 받침을 선으로 이어 보세요.","pairs":[{"l":"삶","r":"ㄻ"},{"l":"굵다","r":"ㄺ"},{"l":"얇다","r":"ㄼ"}],"mis":"K1-2-u2-X05","explanation":["「삶」은 ㄻ, 「굵」은 ㄺ이에요.","「얇」은 ㄼ이에요.","끝소리 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#10','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',2,'blank','auto','빈칸에 알맞은 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#11','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',2,'mc','auto','「흙이」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u2-X08']::text[],false,'{"seq":11,"concept":"K1-2-u2-C3","difficulty":2,"kind":"mc","stem":"「흙이」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[흘기]","correct":true},{"t":"[흐기]","mis":"K1-2-u2-X08"},{"t":"[흑이]","mis":"K1-2-u2-X08"}],"explanation":["뒤에 모음이 오니 둘 다 소리 나요.","「흙[흑]」과 달라요.","뒤에 오는 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#12','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',2,'mc','auto','「화분에 물을 주고 가요」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":12,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「화분에 물을 주고 가요」를 읽고 답하세요. 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"당번은 잊지 말고 화분에 물을 주자","correct":true},{"t":"화분을 새로 사자","mis":"K1-2-u2-X11"},{"t":"잎이 마른다","mis":"K1-2-u2-X11"}],"explanation":["제목과 셋째 줄이 같은 말이에요.","「잎이 마른다」는 물을 주어야 하는 까닭이에요.","제목과 까닭을 이어요."],"asset":{"type":"passage","lines":["우리 반 화분은 사흘에 한 번 물을 줍니다.","물을 주지 않으면 잎이 마릅니다.","당번은 잊지 말고 물을 주고 갑시다."],"title":"화분에 물을 주고 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#13','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',2,'match','auto','「기다려지는 때」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K1-2-u2-C5","difficulty":2,"kind":"match","stem":"「기다려지는 때」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.","pairs":[{"l":"연서","r":"같은 것을 물었다"},{"l":"조리사 선생님","r":"국이 끓는 때라고 답했다"},{"l":"체육 선생님","r":"해가 드는 때라고 답했다"}],"mis":"K1-2-u2-X13","explanation":["연서는 물었고 선생님들은 답했어요.","조리사는 국, 체육은 해예요.","누가 무엇을 했는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#14','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C6',2,'mc','auto','다음 글에서 겹받침이 있는 낱말은 모두 몇 개인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#15','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',2,'ox','auto','「읽다」와 「익다」는 소리가 같으니 아무거나 써도 돼요.',ARRAY['K1-2-u2-X06']::text[],false,'{"seq":15,"concept":"K1-2-u2-C2","difficulty":2,"kind":"ox","stem":"「읽다」와 「익다」는 소리가 같으니 아무거나 써도 돼요.","answer":"X","reason_options":[{"t":"소리가 같아도 뜻이 다른 낱말이니까","correct":true},{"t":"받침만 다르면 같은 낱말이니까","mis":"K1-2-u2-X06"}],"mis":"K1-2-u2-X06","explanation":["「읽다」는 책을 보다, 「익다」는 열매가 익다예요.","뜻이 다르면 다른 낱말이에요.","뜻을 그림으로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#16','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',2,'mc','auto','「화분에 물을 주고 가요」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?',ARRAY['K1-2-u2-X11']::text[],false,'{"seq":16,"concept":"K1-2-u2-C4","difficulty":2,"kind":"mc","stem":"「화분에 물을 주고 가요」를 읽고 답하세요. 글쓴이가 이 글을 쓴 까닭은 무엇인가요?","options":[{"t":"물을 주지 않으면 잎이 말라서","correct":true},{"t":"화분이 예뻐서","mis":"K1-2-u2-X11"},{"t":"당번이 많아서","mis":"K1-2-u2-X11"}],"explanation":["둘째 줄에 까닭이 있어요.","화분 모양이나 당번 수와는 상관없어요.","글쓴이가 걱정하는 일을 찾아요."],"asset":{"type":"passage","lines":["우리 반 화분은 사흘에 한 번 물을 줍니다.","물을 주지 않으면 잎이 마릅니다.","당번은 잊지 말고 물을 주고 갑시다."],"title":"화분에 물을 주고 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#17','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C1',3,'error','auto','겹받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#18','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',3,'error','auto','「밥을 먹고 자리에 안자요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?',ARRAY['K1-2-u2-X04','K1-2-u2-X05']::text[],false,'{"seq":18,"concept":"K1-2-u2-C2","difficulty":3,"kind":"error","stem":"「밥을 먹고 자리에 안자요.」 이 문장에서 잘못 쓴 낱말과 그 까닭은 무엇인가요?","options":[{"t":"「안자요」 — 소리대로 썼어요. 「앉아요」예요","correct":true,"mis_target":"K1-2-u2-X04"},{"t":"「밥을」 — 「바블」로 써야 해요","mis":"K1-2-u2-X05"},{"t":"「자리」 — 받침을 넣어야 해요","mis":"K1-2-u2-X05"}],"explanation":["[안자요]로 들려도 「앉아요」라고 써요.","「밥을」과 「자리」는 바르게 썼어요.","낱말대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#19','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C3',3,'ox','auto','「넓고」와 「넓어」에서 「넓」의 소리는 같아요.',ARRAY['K1-2-u2-X07']::text[],false,'{"seq":19,"concept":"K1-2-u2-C3","difficulty":3,"kind":"ox","stem":"「넓고」와 「넓어」에서 「넓」의 소리는 같아요.","answer":"X","reason_options":[{"t":"뒤에 자음이 오면 하나만, 모음이 오면 둘 다 소리 나니까","correct":true},{"t":"같은 글자면 소리도 언제나 같으니까","mis":"K1-2-u2-X07"}],"mis":"K1-2-u2-X07","explanation":["「넓고」는 [널꼬], 「넓어」는 [널버]예요.","같은 글자여도 뒤에 오는 것에 따라 달라져요.","두 낱말을 소리 내어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#20','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',3,'mc','auto','「제일 좋아하는 소리」에서 세 사람의 답이 다 다른 까닭은 무엇일까요?',ARRAY['K1-2-u2-X14','K1-2-u2-X13']::text[],false,'{"seq":20,"concept":"K1-2-u2-C5","difficulty":3,"kind":"mc","stem":"「제일 좋아하는 소리」에서 세 사람의 답이 다 다른 까닭은 무엇일까요?","options":[{"t":"저마다 하는 일이 달라서","correct":true},{"t":"한 사람만 소리를 좋아해서","mis":"K1-2-u2-X14"},{"t":"연우가 잘못 들어서","mis":"K1-2-u2-X13"}],"explanation":["음악·급식·경비 하는 일이 다 달라요.","좋아하는 소리는 하는 일과 이어져요.","다섯째 줄 연우의 생각을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#21','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',3,'error','auto','하고 싶은 말을 찾는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#22','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C6',3,'ox','auto','둘레에서 찾은 겹받침 낱말은 소리 내어 읽어 보면 좋아요.',ARRAY['K1-2-u2-X15']::text[],false,'{"seq":22,"concept":"K1-2-u2-C6","difficulty":3,"kind":"ox","stem":"둘레에서 찾은 겹받침 낱말은 소리 내어 읽어 보면 좋아요.","answer":"O","reason_options":[{"t":"바르게 읽는 법까지 함께 익혀지니까","correct":true},{"t":"소리 내어 읽으면 카드가 예뻐지니까","mis":"K1-2-u2-X15"}],"mis":"K1-2-u2-X15","explanation":["찾기 → 읽기 → 쓰기가 함께 가요.","카드 모양과는 상관없어요.","찾은 낱말은 꼭 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#23','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C2',4,'sa','auto','[닥]이라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (꼬꼬댁 우는 새)','{}'::text[],false,'{"seq":23,"concept":"K1-2-u2-C2","difficulty":4,"kind":"sa","stem":"[닥]이라고 소리 나는 낱말을 뜻에 맞게 바르게 쓰세요. (꼬꼬댁 우는 새)","answer":["닭"],"explanation":["꼬꼬댁 우는 새는 「닭」이에요.","소리는 [닥]이지만 받침은 ㄺ이에요.","뜻을 떠올리고 겹받침을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#24','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C5',4,'essay','teacher','「기다려지는 때」를 읽고, 체육 선생님의 말에서 어떤 생각을 하는지 짐작해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u2-C5","difficulty":4,"kind":"essay","stem":"「기다려지는 때」를 읽고, 체육 선생님의 말에서 어떤 생각을 하는지 짐작해 쓰세요.","answer_guide":{"answer":"예: 체육 선생님은 운동장에서 아이들과 운동하는 것을 좋아한다. — 해가 드는 때를 기다린다는 말과 이어서 짐작하면 맞아요.","scoring_points":["체육 선생님의 말을 근거로 썼는가","운동장·운동과 이어지는가","내 생각이 아니라 인물의 말에서 짐작했는가"]},"explanation":["체육 선생님은 운동장에 해가 드는 때를 기다린다고 했어요.","그 말에서 운동장에서 하는 일을 소중히 여기는 생각이 보여요.","말과 행동에서 짐작해요."],"asset":{"type":"passage","lines":["연서는 학교를 돌아다니며 같은 것을 물었어요. \"가장 기다려지는 때는 언제예요?\"","조리사 선생님이 말했어요. \"국이 알맞게 끓는 때란다.\"","도서관 선생님이 말했어요. \"아이들이 책을 읽는 때예요.\"","체육 선생님이 말했어요. \"운동장에 해가 드는 때지.\"","연서는 생각했어요. ''물음은 하나인데 답이 다 다르구나.''"],"title":"기다려지는 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u2_review_d#25','kor',1,2,'u2','','g1_2_kor_u2_review_d','unit_review','K1-2-u2-C4',4,'essay','teacher','「화분에 물을 주고 가요」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u2-C4","difficulty":4,"kind":"essay","stem":"「화분에 물을 주고 가요」를 읽고, 제목과 쓴 까닭을 이어 글쓴이가 하고 싶은 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 잎이 마르지 않게 당번은 잊지 말고 화분에 물을 주자. — 하고 싶은 말과 까닭이 이어져 있으면 맞아요.","scoring_points":["「물을 주자」는 말이 있는가","까닭(잎이 마른다)을 이었는가","한 줄만 베끼지 않았는가"]},"explanation":["제목이 하고 싶은 말이에요.","둘째 줄이 까닭이에요.","둘을 「~니까 ~하자」로 이어요."],"asset":{"type":"passage","lines":["우리 반 화분은 사흘에 한 번 물을 줍니다.","물을 주지 않으면 잎이 마릅니다.","당번은 잊지 말고 물을 주고 갑시다."],"title":"화분에 물을 주고 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
